DECLARE
    v_object text;
    v_others int;
BEGIN
    SELECT max(object_name) INTO v_object FROM storeplan_schema WHERE kind = 'RANGE_INDEX' AND label = 'Person' AND properties = '["address.city"]';
    SELECT count(*) INTO v_others FROM storeplan_schema WHERE object_name = v_object AND NOT (kind = 'RANGE_INDEX' AND label = 'Person' AND properties = '["address.city"]');
    IF v_object IS NOT NULL AND v_others = 0 THEN
        -- Written bare, as it was made: Postgres folds the name to lower case either way.
        EXECUTE 'DROP INDEX IF EXISTS ' || v_object;
    END IF;
    DELETE FROM storeplan_schema WHERE kind = 'RANGE_INDEX' AND label = 'Person' AND properties = '["address.city"]';
END
