DECLARE
    v_object text;
    v_others int;
BEGIN
    SELECT max(object_name) INTO v_object FROM <graph-1>_schema WHERE kind = 'UNIQUENESS_CONSTRAINT' AND label = 'Pet' AND properties = '["id"]';
    SELECT count(*) INTO v_others FROM <graph-1>_schema WHERE object_name = v_object AND NOT (kind = 'UNIQUENESS_CONSTRAINT' AND label = 'Pet' AND properties = '["id"]');
    IF v_object IS NOT NULL AND v_others = 0 THEN
        -- Written bare, as it was made: Postgres folds the name to lower case either way.
        EXECUTE 'DROP INDEX IF EXISTS ' || v_object;
    END IF;
    DELETE FROM <graph-1>_schema WHERE kind = 'UNIQUENESS_CONSTRAINT' AND label = 'Pet' AND properties = '["id"]';
END
