DECLARE
    v_object text;
    v_others int;
BEGIN
    SELECT max(object_name) INTO v_object FROM identity_schema WHERE kind = 'UNIQUENESS_CONSTRAINT' AND label = 'DrivineStore' AND properties = '["key"]';
    SELECT count(*) INTO v_others FROM identity_schema WHERE object_name = v_object AND NOT (kind = 'UNIQUENESS_CONSTRAINT' AND label = 'DrivineStore' AND properties = '["key"]');
    IF v_object IS NOT NULL AND v_others = 0 THEN
        -- Written bare, as it was made: Postgres folds the name to lower case either way.
        EXECUTE 'DROP INDEX IF EXISTS ' || v_object;
    END IF;
    DELETE FROM identity_schema WHERE kind = 'UNIQUENESS_CONSTRAINT' AND label = 'DrivineStore' AND properties = '["key"]';
END
