    v_others int;
BEGIN
    SELECT max(object_name) INTO v_object FROM storeplan_schema WHERE kind = 'RANGE_INDEX' AND label = 'Person' AND properties = '["o''name"]';
    SELECT count(*) INTO v_others FROM storeplan_schema WHERE object_name = v_object AND NOT (kind = 'RANGE_INDEX' AND label = 'Person' AND properties = '["o''name"]');
    IF v_object IS NOT NULL AND v_others = 0 THEN
        -- Written bare, as it was made: Postgres folds the name to lower case either way.
        EXECUTE 'DROP INDEX IF EXISTS ' || v_object;
    END IF;
    DELETE FROM storeplan_schema WHERE kind = 'RANGE_INDEX' AND label = 'Person' AND properties = '["o''name"]';
END
$forget$

DO $ensure$
BEGIN
    IF obj_description(to_regclass('ftbm25i_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
        PERFORM pg_advisory_xact_lock(hashtext('drivine:ftbm25i'));
        -- Looked for again under the lock: another session may have made it while this one waited.
        IF obj_description(to_regclass('ftbm25i_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
            -- pgvector, for vector search, where the server has it and the user may make it: without it,
            -- everything but a vector search works.
            BEGIN
                CREATE EXTENSION IF NOT EXISTS vector;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            CREATE TABLE IF NOT EXISTS ftbm25i_node (
        nid    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        labels jsonb NOT NULL,
        props  jsonb NOT NULL,
        stamp  varchar(33)
    );
    CREATE TABLE IF NOT EXISTS ftbm25i_edge (
        eid   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        src   bigint NOT NULL REFERENCES ftbm25i_node (nid) ON DELETE CASCADE,
        dst   bigint NOT NULL REFERENCES ftbm25i_node (nid) ON DELETE CASCADE,
        type  varchar(128) NOT NULL,
        props jsonb NOT NULL DEFAULT '{}'
    );
    CREATE TABLE IF NOT EXISTS ftbm25i_schema (
        kind        varchar(40) NOT NULL,
        label       varchar(400) NOT NULL,
        properties  varchar(2000) NOT NULL,
        name        varchar(400),
        object_name varchar(63),
        details     jsonb NOT NULL,
        PRIMARY KEY (kind, label, properties)
    );
    CREATE INDEX IF NOT EXISTS ftbm25i_edge_src ON ftbm25i_edge (src, type);
    CREATE INDEX IF NOT EXISTS ftbm25i_edge_dst ON ftbm25i_edge (dst, type);
    CREATE INDEX IF NOT EXISTS ftbm25i_node_labels ON ftbm25i_node USING GIN (labels jsonb_path_ops);
    CREATE OR REPLACE FUNCTION ftbm25i_find(p_labels jsonb, p_key text, p_id text) RETURNS ftbm25i_node AS $fn$
    DECLARE
        -- The lookup of a shape is prepared once a session and run by name after: written for the shape, it
        -- is planned for its label and property, and planned again each time it would cost a lookup several
        -- times over. The name is a hash of what the lookup is for, so it fits whatever the graph is called.
        v_name  text := 'drivine_find_' || md5('ftbm25i' || ' ' || p_key || ' ' || p_labels::text);
        v_nid   bigint;
        v_row   ftbm25i_node;
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_name) THEN
            -- Each label is a test of its own, as a statement writes it, so a partial index over one is used.
            EXECUTE format('PREPARE %I (text) AS SELECT min(n.nid) FROM ftbm25i_node n WHERE (n.props ->> %L) = $1', v_name, p_key) ||
                COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(p_labels) l), '');
        END IF;
        LOOP
            EXECUTE format('EXECUTE %I(%L)', v_name, p_id) INTO v_nid;
            IF v_nid IS NULL THEN
                RETURN NULL;
            END IF;
            SELECT * INTO v_row FROM ftbm25i_node n WHERE n.nid = v_nid FOR UPDATE;
            -- Locked: is it still the node that was looked for? Another writer may have changed it meanwhile.
            IF FOUND AND v_row.props ->> p_key = p_id AND v_row.labels @> p_labels THEN
                RETURN v_row;
            END IF;
        END LOOP;
    END
    $fn$ LANGUAGE plpgsql;
    CREATE OR REPLACE FUNCTION ftbm25i_owns(p_bag jsonb, p_key text) RETURNS boolean AS $fn$
    DECLARE
        v_prefix   text := p_bag ->> 'prefix';
        v_reserved text;
    BEGIN
        -- A bag with a prefix owns the keys that begin with it; a flat bag, each key that is no one else's.
        IF NOT COALESCE((p_bag ->> 'flat')::boolean, false) THEN
            RETURN length(p_key) > COALESCE(length(v_prefix), 0) AND (v_prefix IS NULL OR left(p_key, length(v_prefix)) = v_prefix);
        END IF;
        IF COALESCE(p_bag -> 'reservedKeys', '[]'::jsonb) @> to_jsonb(p_key) THEN
            RETURN false;
        END IF;
        FOR v_reserved IN SELECT jsonb_array_elements_text(COALESCE(p_bag -> 'reservedPrefixes', '[]'::jsonb)) LOOP
            IF left(p_key, length(v_reserved)) = v_reserved THEN
                RETURN false;
            END IF;
        END LOOP;
        RETURN true;
    END
    $fn$ LANGUAGE plpgsql IMMUTABLE;
    CREATE OR REPLACE FUNCTION ftbm25i_lowered(p_props jsonb, p_keys jsonb) RETURNS jsonb AS $fn$
    DECLARE
        v_props jsonb := p_props;
        v_key   text;
    BEGIN
        FOR v_key IN SELECT jsonb_array_elements_text(COALESCE(p_keys, '[]'::jsonb)) LOOP
            IF v_props ->> v_key IS NULL THEN
                v_props := v_props - ('__drivine.lower.' || v_key);
            ELSE
                v_props := v_props || jsonb_build_object('__drivine.lower.' || v_key, lower(v_props ->> v_key));
            END IF;
        END LOOP;
        RETURN v_props;
    END
    $fn$ LANGUAGE plpgsql STABLE;
    CREATE OR REPLACE FUNCTION ftbm25i_write(p_plan jsonb, p_shapes jsonb, p_mark text, p_returns text, p_patched_if text) RETURNS SETOF text AS $fn$
    DECLARE
        v_op        jsonb;
        v_shape     jsonb;
        v_nodes     bigint[] := '{}';
        v_h_index   text[] := '{}';
        v_h_found   text[] := '{}';
        v_h_node    bigint[] := '{}';
        v_relinks   bigint[] := '{}';
        v_root      bigint;
        v_root_made boolean := false;
        v_was       text;
        v_carried   text;
        v_stamp     text;
        v_count     bigint := 0;
        v_result    text;
        v_each      text[] := '{}';
        v_stale     boolean := false;
        -- A node step's.
        v_row       ftbm25i_node;
        v_nid       bigint;
        v_found     text;
        v_two       text;
        v_labels    jsonb;
        v_o         jsonb;
        v_expect    text;
        v_fresh     text;
        v_add       jsonb;
        v_drop      jsonb;
        v_made      boolean;
        v_tries     int;
        v_relabel   boolean;
        v_bag       jsonb;
        v_key       text;
        v_owned     jsonb;
        v_recorded  jsonb;
        v_now       jsonb;
        v_same      boolean;
        v_copied    jsonb;
        v_met       bigint;
        v_premade   jsonb := '{}';
        v_after     jsonb;
        v_pre       bigint;
        v_s         int;
        v_premade_as text;
        -- A relationship step's.
        v_from      bigint;
        v_to        bigint;
        v_type      text;
        v_dir       text;
        v_props     jsonb;
        v_clear     jsonb;
        v_e         record;
        v_x         jsonb;
        v_seen      int;
        v_unchanged int;
        v_ids       jsonb;
        v_held      jsonb;
        v_keep      boolean;
        v_delete    boolean;
        v_gone      bigint[];
        v_targets   bigint[];
        v_keys      text[];
        v_target    bigint;
        v_refs      bigint;
        v_removed   bigint;
    BEGIN
        BEGIN
            -- The nodes the plan makes, made together. A `node` step that does no more than write properties,
            -- with no stamp to check, no property bag to clear and no labels to own, makes its node by an
            -- insert alone when the node is not there; so for each shape the nodes of such steps that are not
            -- there are found by one lookup and inserted by one statement, the first step for each id only. A
            -- node a uniqueness constraint refuses, made by another writer at this moment, is not inserted
            -- here: its step finds it, or is refused, as it would be on its own. What each made gets is in
            -- `v_premade`, by shape and id, for its step to take below.
            -- Only where a shape has several such steps: for one node, the lookup and insert of its step are as cheap.
            FOR v_s IN
                SELECT (op ->> 's')::int FROM jsonb_array_elements(p_plan) op
                WHERE op ->> 'op' = 'node' AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                GROUP BY 1 HAVING count(*) > 1
            LOOP
                v_shape := p_shapes -> v_s;
                -- Prepared once a session for the shape, as a lookup is, and run by name after: planned afresh,
                -- it costs more than it saves a save of a few nodes. The name holds the store's version too, so
                -- a session that outlives an upgrade does not run what an earlier version prepared.
                v_premade_as := 'drivine_made_' || md5('drivine:7 ftbm25i' || ' ' || (v_shape ->> 'key') || ' ' || (v_shape -> 'labels')::text);
                IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_premade_as) THEN
                    EXECUTE format('PREPARE %I (jsonb, int) AS ', v_premade_as) || format($made$
                        WITH steps AS (
                            SELECT DISTINCT ON (op ->> 'k') ord, op FROM jsonb_array_elements($1) WITH ORDINALITY AS t (op, ord)
                            WHERE op ->> 'op' = 'node' AND (op ->> 's')::int = $2 AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                            ORDER BY op ->> 'k', ord),
                        absent AS (
                            SELECT s.ord, s.op FROM steps s
                            WHERE NOT EXISTS (SELECT 1 FROM ftbm25i_node n WHERE (n.props ->> %L) = s.op ->> 'k'%s)),
                        made AS (
                            INSERT INTO ftbm25i_node (labels, props, stamp)
                            SELECT op -> 'labels',
                                   ftbm25i_lowered((jsonb_build_object(op ->> 'key', op -> 'id') || COALESCE(op -> 'set', '{}'::jsonb))
                                       - ARRAY(SELECT jsonb_array_elements_text(COALESCE(op -> 'unset', '[]'::jsonb))), op -> 'lower'),
                                   op ->> 'fresh'
                            FROM absent ORDER BY ord
                            ON CONFLICT DO NOTHING
                            RETURNING nid, props ->> %L AS k)
                        SELECT COALESCE(jsonb_object_agg(k, nid), '{}'::jsonb) FROM made
                    $made$, v_shape ->> 'key',
                        COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(v_shape -> 'labels') l), ''),
                        v_shape ->> 'key');
                END IF;
                EXECUTE format('EXECUTE %I(%L, %s)', v_premade_as, p_plan, v_s) INTO v_after;
                v_premade := v_premade || jsonb_build_object(v_s::text, v_after);
            END LOOP;

            FOR v_op IN SELECT value FROM jsonb_array_elements(p_plan) LOOP
                CASE v_op ->> 'op'
                WHEN 'node' THEN
                    -- Saves a node: found and locked, or made. What the step writes is worked out over the node as
                    -- it was found, and the node is written only where that differs from what it holds.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_expect := v_op ->> 'expect';
                    v_fresh := v_op ->> 'fresh';
                    v_tries := 0;
                    -- A node made with the others above is this step's, once: a later step for the same id finds it.
                    v_pre := (v_premade -> (v_op ->> 's') ->> (v_op ->> 'k'))::bigint;
                    IF v_pre IS NOT NULL THEN
                        v_premade := v_premade #- ARRAY[v_op ->> 's', v_op ->> 'k'];
                        v_nid := v_pre;
                        v_made := true;
                        v_found := NULL;
                    END IF;
                    WHILE v_pre IS NULL LOOP
                        v_row := ftbm25i_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                        v_made := v_row.nid IS NULL;
                        IF v_made THEN
                            -- A checked save does not make the node again: it is gone, and the object is stale.
                            -- Nor does a step that makes no node.
                            IF v_expect IS NOT NULL OR NOT COALESCE((v_op ->> 'create')::boolean, true) THEN
                                RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                            END IF;
                            v_labels := v_op -> 'labels';
                            v_o := jsonb_build_object(v_op ->> 'key', v_op -> 'id');
                            v_stamp := NULL;
                        ELSIF COALESCE((v_op ->> 'absent')::boolean, false) THEN
                            -- A step that only makes the node writes nothing to one that is there.
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        ELSE
                            v_labels := v_row.labels;
                            v_o := v_row.props;
                            v_stamp := v_row.stamp;
                        END IF;
                        v_found := v_stamp;
                        IF v_expect IS NOT NULL AND (v_stamp IS NULL OR
                                CASE WHEN COALESCE((v_op ->> 'whole')::boolean, false) THEN v_stamp ELSE substr(v_stamp, 1, 16) END <> v_expect) THEN
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        END IF;

                        -- The properties the step sets, and without those it unsets.
                        v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        -- The keys of each property bag the object no longer holds.
                        FOR v_bag IN SELECT value FROM jsonb_array_elements(COALESCE(v_op -> 'bags', '[]'::jsonb)) LOOP
                            FOR v_key IN SELECT jsonb_object_keys(v_o) LOOP
                                IF NOT COALESCE(v_bag -> 'keep', '[]'::jsonb) @> to_jsonb(v_key) AND ftbm25i_owns(v_bag, v_key) THEN
                                    v_o := v_o - v_key;
                                END IF;
                            END LOOP;
                        END LOOP;

                        -- The labels an open label field holds are recorded on the node, so the node knows which are
                        -- its own. A step that clears replaces the record, and drops the labels recorded that the
                        -- field no longer holds, but for those of the class; one that does not adds to the record.
                        v_add := COALESCE(v_op -> 'add', '[]'::jsonb);
                        v_drop := COALESCE(v_op -> 'drop', '[]'::jsonb);
                        v_owned := v_op -> 'owned';
                        IF v_owned IS NOT NULL THEN
                            v_recorded := v_o -> (v_owned ->> 'prop');
                            IF v_recorded IS NULL OR jsonb_typeof(v_recorded) <> 'array' THEN
                                v_recorded := '[]'::jsonb;
                            END IF;
                            IF COALESCE((v_owned ->> 'clear')::boolean, false) THEN
                                v_drop := v_drop || COALESCE((
                                    SELECT jsonb_agg(l) FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l) AND NOT COALESCE(v_owned -> 'base', '[]'::jsonb) @> to_jsonb(l)), '[]'::jsonb);
                                IF jsonb_array_length(v_add) = 0 THEN
                                    v_o := v_o - (v_owned ->> 'prop');
                                ELSE
                                    v_o := v_o || jsonb_build_object(v_owned ->> 'prop', v_add);
                                END IF;
                            ELSIF jsonb_array_length(v_add) > 0 THEN
                                v_o := v_o || jsonb_build_object(v_owned ->> 'prop', COALESCE((
                                    SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l)), '[]'::jsonb) || v_add);
                            END IF;
                        END IF;

                        -- The node's labels with those the step adds and without those it drops, in order; labels
                        -- that are as they were are not written again.
                        v_relabel := false;
                        IF jsonb_array_length(v_add) > 0 OR jsonb_array_length(v_drop) > 0 THEN
                            v_now := COALESCE((
                                SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM (
                                    SELECT jsonb_array_elements_text(v_labels) AS l UNION SELECT jsonb_array_elements_text(v_add)
                                ) a WHERE NOT v_drop @> to_jsonb(l)), '[]'::jsonb);
                            v_relabel := NOT (v_now @> v_labels AND v_labels @> v_now);
                            IF v_relabel OR v_made THEN
                                v_labels := v_now;
                            END IF;
                        END IF;

                        -- The copies are written from what the step leaves, and are no part of whether it changed the node.
                        v_copied := ftbm25i_lowered(v_o, v_op -> 'lower');
                        IF v_made THEN
                            -- A node that is made is written once, whole, with a stamp of its own. A uniqueness
                            -- constraint may refuse it: once, it may be that another writer made the node at this
                            -- moment, and the node is looked for again. Found again or not, the constraint is on
                            -- something other than this node's key, and refuses this save.
                            v_stamp := v_fresh;
                            INSERT INTO ftbm25i_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp) ON CONFLICT DO NOTHING RETURNING nid INTO v_nid;
                            IF v_nid IS NOT NULL THEN
                                EXIT;
                            END IF;
                            v_tries := v_tries + 1;
                            IF v_tries > 1 THEN
                                INSERT INTO ftbm25i_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp);
                            END IF;
                        ELSE
                            v_nid := v_row.nid;
                            v_same := v_o = v_row.props;
                            -- A new first token only if the step changes the node, or the node has no stamp of two tokens yet.
                            v_two := CASE WHEN length(v_stamp) = 33 AND substr(v_stamp, 17, 1) = ':' THEN v_stamp END;
                            IF v_two IS NULL OR NOT v_same OR v_relabel THEN
                                v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                                IF v_relabel THEN
                                    UPDATE ftbm25i_node SET labels = v_labels WHERE nid = v_nid;
                                END IF;
                                IF v_copied <> v_row.props THEN
                                    UPDATE ftbm25i_node SET props = v_copied, stamp = v_stamp WHERE nid = v_nid;
                                ELSE
                                    UPDATE ftbm25i_node SET stamp = v_stamp WHERE nid = v_nid;
                                END IF;
                            ELSIF v_copied <> v_row.props THEN
                                -- Only a copy was out of step with its property: the node keeps its stamp.
                                UPDATE ftbm25i_node SET props = v_copied WHERE nid = v_nid;
                            END IF;
                            EXIT;
                        END IF;
                    END LOOP;

                    v_nodes[(v_op ->> 'r')::int + 1] := v_nid;
                    IF v_op ->> 'i' IS NOT NULL THEN
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        -- Nothing for a node the step made, and a mark for one that was there without a stamp.
                        v_h_found := array_append(v_h_found, CASE WHEN v_made THEN NULL ELSE COALESCE(v_found, '-') END);
                        v_h_node := array_append(v_h_node, v_nid);
                    END IF;
                    IF COALESCE((v_op ->> 'root')::boolean, false) THEN
                        v_root := v_nid;
                        v_root_made := v_made;
                        v_was := v_found;
                        v_carried := v_op ->> 'carried';
                    END IF;

                WHEN 'ref' THEN
                    -- Finds a node that must be there, and locks it.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_row := ftbm25i_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NULL THEN
                        RAISE EXCEPTION 'absent' USING ERRCODE = 'P0D02';
                    END IF;
                    v_nodes[(v_op ->> 'r')::int + 1] := v_row.nid;

                WHEN 'link' THEN
                    -- Joins two nodes. The relationship is as the step says only if every one of its type between them is.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := v_nodes[(v_op ->> 'to')::int + 1];
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_props := COALESCE(v_op -> 'props', '{}'::jsonb);
                    v_clear := COALESCE(v_op -> 'clear', '[]'::jsonb);
                    v_seen := 0;
                    v_unchanged := 0;
                    IF NOT COALESCE((v_op ->> 'always')::boolean, false) THEN
                        -- A node's relationship to itself is one relationship, whichever way it is read.
                        FOR v_e IN
                            SELECT eid, props FROM ftbm25i_edge
                            WHERE type = v_type AND (
                                (v_dir IN ('OUT', 'BOTH') AND src = v_from AND dst = v_to)
                                OR ((v_dir = 'IN' OR (v_dir = 'BOTH' AND v_from <> v_to)) AND src = v_to AND dst = v_from))
                            ORDER BY eid
                        LOOP
                            v_seen := v_seen + 1;
                            v_x := (v_e.props || v_props) - ARRAY(SELECT jsonb_array_elements_text(v_clear));
                            IF v_x = v_e.props THEN
                                v_unchanged := v_unchanged + 1;
                            ELSE
                                UPDATE ftbm25i_edge SET props = v_x WHERE eid = v_e.eid;
                            END IF;
                        END LOOP;
                    END IF;
                    IF v_seen = 0 THEN
                        -- An undirected field is satisfied by a relationship either way, and makes one from the first node.
                        INSERT INTO ftbm25i_edge (src, dst, type, props)
                        VALUES (CASE WHEN v_dir = 'IN' THEN v_to ELSE v_from END, CASE WHEN v_dir = 'IN' THEN v_from ELSE v_to END, v_type, v_props);
                    END IF;
                    IF v_seen = 0 OR v_unchanged < v_seen THEN
                        v_relinks := v_relinks || v_from || v_to;
                    END IF;
                    v_count := v_count + GREATEST(v_seen, 1);

                WHEN 'unlink' THEN
                    -- Removes a field's relationships to the targets whose ids the step names, or to every target but those.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_ids := COALESCE(v_op -> 'ids', '[]'::jsonb);
                    v_held := COALESCE(v_op -> 'held', '[]'::jsonb);
                    v_keep := COALESCE((v_op ->> 'keep')::boolean, false);
                    v_delete := COALESCE((v_op ->> 'delete')::boolean, false);
                    v_gone := '{}';
                    v_targets := '{}';
                    v_keys := '{}';
                    -- A relationship from the node to itself is read as leaving it, and so once when both directions are read.
                    FOR v_e IN
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key') AS key
                        FROM ftbm25i_edge e JOIN ftbm25i_node t ON t.nid = e.dst
                        WHERE v_dir IN ('OUT', 'BOTH') AND e.src = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                        UNION ALL
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key')
                        FROM ftbm25i_edge e JOIN ftbm25i_node t ON t.nid = e.src
                        WHERE v_dir IN ('IN', 'BOTH') AND e.dst = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                          AND (v_dir = 'IN' OR e.src <> v_from)
                    LOOP
                        IF v_e.key IS NOT NULL AND (v_ids @> to_jsonb(v_e.key)) <> v_keep THEN
                            v_gone := array_append(v_gone, v_e.eid);
                            v_targets := array_append(v_targets, v_e.nid);
                            v_keys := array_append(v_keys, v_e.key);
                        END IF;
                    END LOOP;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- A target gone since the relationships were read has nothing left to remove or count.
                            PERFORM 1 FROM ftbm25i_node WHERE nid = v_target FOR UPDATE;
                            IF NOT FOUND THEN
                                CONTINUE;
                            END IF;
                            -- What refers to a target is a relationship on the side this field reaches it from: counted before any is removed.
                            v_refs := 0;
                            IF v_delete THEN
                                IF v_dir IN ('OUT', 'BOTH') THEN
                                    SELECT count(*) INTO v_refs FROM ftbm25i_edge WHERE dst = v_target;
                                END IF;
                                IF v_dir IN ('IN', 'BOTH') THEN
                                    -- A relationship from the node to itself is counted once.
                                    SELECT v_refs + count(*) INTO v_refs FROM ftbm25i_edge WHERE src = v_target AND (v_dir = 'IN' OR dst <> v_target);
                                END IF;
                            END IF;
                            SELECT count(*) INTO v_removed FROM unnest(v_targets) t WHERE t = v_target;
                            SELECT k INTO v_key FROM unnest(v_targets, v_keys) AS u (t, k) WHERE t = v_target LIMIT 1;
                            -- The root is never deleted, and nor is a node the object still holds in another field.
                            IF v_delete AND v_target <> v_from AND v_refs = v_removed AND NOT v_held @> to_jsonb(v_key) THEN
                                v_relinks := array_remove(v_relinks, v_target);
                                DELETE FROM ftbm25i_node WHERE nid = v_target;
                            ELSE
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM ftbm25i_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'cut' THEN
                    -- Removes the relationships of a type from one node to another, or with no other node named to any in a direction.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := CASE WHEN v_op ->> 'to' IS NOT NULL THEN v_nodes[(v_op ->> 'to')::int + 1] END;
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    SELECT COALESCE(array_agg(c.eid), '{}'), COALESCE(array_agg(c.far), '{}') INTO v_gone, v_targets FROM (
                        SELECT eid, dst AS far FROM ftbm25i_edge
                        WHERE v_dir IN ('OUT', 'BOTH') AND src = v_from AND type = v_type AND (v_to IS NULL OR dst = v_to)
                        UNION ALL
                        SELECT eid, src FROM ftbm25i_edge
                        WHERE v_dir IN ('IN', 'BOTH') AND dst = v_from AND type = v_type AND (v_to IS NULL OR src = v_to) AND (v_dir = 'IN' OR src <> v_from)
                    ) c;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- An end gone since the relationships were read took them with it, and has no token to change.
                            PERFORM 1 FROM ftbm25i_node WHERE nid = v_target FOR UPDATE;
                            IF FOUND THEN
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM ftbm25i_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'patch' THEN
                    -- Writes properties to a node that is there, and makes none. One that is not there is left out of
                    -- what the call hands back; one that does not meet the predicate is left as it is, and said to.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_fresh := v_op ->> 'fresh';
                    v_row := ftbm25i_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NOT NULL THEN
                        v_met := 1;
                        IF p_patched_if IS NOT NULL THEN
                            -- The node is locked: what the predicate reads of it is what the last writer committed.
                            EXECUTE p_patched_if INTO v_met USING v_row.nid;
                        END IF;
                        v_o := v_row.props;
                        IF v_met > 0 THEN
                            v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        END IF;
                        v_same := v_o = v_row.props;
                        -- A node the step changes has its copies written from what it now holds.
                        IF NOT v_same THEN
                            v_o := ftbm25i_lowered(v_o, v_op -> 'lower');
                        END IF;
                        v_two := CASE WHEN length(v_row.stamp) = 33 AND substr(v_row.stamp, 17, 1) = ':' THEN v_row.stamp END;
                        IF v_two IS NULL OR NOT v_same THEN
                            v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                            IF NOT v_same THEN
                                UPDATE ftbm25i_node SET props = v_o, stamp = v_stamp WHERE nid = v_row.nid;
                            ELSE
                                UPDATE ftbm25i_node SET stamp = v_stamp WHERE nid = v_row.nid;
                            END IF;
                        END IF;
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        v_h_found := array_append(v_h_found, CASE WHEN v_met = 0 THEN '-' WHEN NOT v_same THEN '1' ELSE '0' END);
                        v_h_node := array_append(v_h_node, v_row.nid);
                    END IF;
                END CASE;
            END LOOP;

            -- Each node whose relationships changed gets a new second token, once. Every one of them is locked
            -- already, found and locked by its step or made by it, so one statement writes them all and waits
            -- for no lock. A stamp that is not two tokens, which no save leaves, is replaced whole.
            IF cardinality(v_relinks) > 0 THEN
                UPDATE ftbm25i_node SET stamp = COALESCE(substr(CASE WHEN length(stamp) = 33 AND substr(stamp, 17, 1) = ':' THEN stamp END, 1, 17), substr(p_mark, 1, 17)) || substr(p_mark, 18)
                WHERE nid = ANY (v_relinks);
            END IF;

            IF p_returns = 'STAMPS' THEN
                -- The root's stamp, keeping the object's own token wherever the node had another when the save
                -- began, then `index/found=stamp` for each node whose stamp is handed back.
                SELECT stamp INTO v_stamp FROM ftbm25i_node WHERE nid = v_root;
                IF v_carried IS NULL THEN
                    -- An object that carried no stamp is handed the whole stamp only of a node its save made.
                    IF NOT v_root_made THEN
                        v_stamp := substr(v_stamp, 1, 17);
                    END IF;
                ELSIF v_was = v_carried THEN
                    NULL; -- found exactly as loaded: the node's stamp is handed back whole
                ELSE
                    v_stamp := CASE WHEN substr(v_was, 1, 16) = substr(v_carried, 1, 16) THEN substr(v_stamp, 1, 16) ELSE substr(v_carried, 1, 16) END || ':' ||
                        CASE WHEN NULLIF(substr(v_was, 18), '') = NULLIF(substr(v_carried, 18), '') OR (v_root_made AND NULLIF(substr(v_carried, 18), '') IS NULL)
                             THEN substr(v_stamp, 18) ELSE substr(v_carried, 18) END;
                END IF;
                -- Every handed-back stamp is read by one query, in the order the steps came.
                SELECT v_stamp || COALESCE(string_agg(',' || h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, ''), '' ORDER BY h.ord), '')
                INTO v_result
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN ftbm25i_node n ON n.nid = h.nid;
            ELSIF p_returns = 'EACH_STAMP' THEN
                SELECT COALESCE(array_agg(h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, '') ORDER BY h.ord), '{}')
                INTO v_each
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN ftbm25i_node n ON n.nid = h.nid;
            END IF;
        EXCEPTION
            WHEN SQLSTATE 'P0D01' THEN v_stale := true; -- rolled back: nothing was written
            WHEN SQLSTATE 'P0D02' THEN v_count := 0;   -- a node the plan refers to is not there: rolled back, nothing was written
        END;
        IF p_returns = 'STAMPS' THEN
            IF NOT v_stale AND v_result IS NOT NULL THEN
                RETURN NEXT v_result;
            END IF;
        ELSIF p_returns = 'EACH_STAMP' THEN
            IF NOT v_stale THEN
                RETURN QUERY SELECT unnest(v_each);
            END IF;
        ELSE
            RETURN NEXT v_count::text;
        END IF;
    END
    $fn$ LANGUAGE plpgsql;
    COMMENT ON TABLE ftbm25i_node IS 'drivine:7';
        END IF;
    END IF;
END
$ensure$

DO $ensure$
BEGIN
    IF obj_description(to_regclass('ftrank_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
        PERFORM pg_advisory_xact_lock(hashtext('drivine:ftrank'));
        -- Looked for again under the lock: another session may have made it while this one waited.
        IF obj_description(to_regclass('ftrank_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
            -- pgvector, for vector search, where the server has it and the user may make it: without it,
            -- everything but a vector search works.
            BEGIN
                CREATE EXTENSION IF NOT EXISTS vector;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            CREATE TABLE IF NOT EXISTS ftrank_node (
        nid    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        labels jsonb NOT NULL,
        props  jsonb NOT NULL,
        stamp  varchar(33)
    );
    CREATE TABLE IF NOT EXISTS ftrank_edge (
        eid   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        src   bigint NOT NULL REFERENCES ftrank_node (nid) ON DELETE CASCADE,
        dst   bigint NOT NULL REFERENCES ftrank_node (nid) ON DELETE CASCADE,
        type  varchar(128) NOT NULL,
        props jsonb NOT NULL DEFAULT '{}'
    );
    CREATE TABLE IF NOT EXISTS ftrank_schema (
        kind        varchar(40) NOT NULL,
        label       varchar(400) NOT NULL,
        properties  varchar(2000) NOT NULL,
        name        varchar(400),
        object_name varchar(63),
        details     jsonb NOT NULL,
        PRIMARY KEY (kind, label, properties)
    );
    CREATE INDEX IF NOT EXISTS ftrank_edge_src ON ftrank_edge (src, type);
    CREATE INDEX IF NOT EXISTS ftrank_edge_dst ON ftrank_edge (dst, type);
    CREATE INDEX IF NOT EXISTS ftrank_node_labels ON ftrank_node USING GIN (labels jsonb_path_ops);
    CREATE OR REPLACE FUNCTION ftrank_find(p_labels jsonb, p_key text, p_id text) RETURNS ftrank_node AS $fn$
    DECLARE
        -- The lookup of a shape is prepared once a session and run by name after: written for the shape, it
        -- is planned for its label and property, and planned again each time it would cost a lookup several
        -- times over. The name is a hash of what the lookup is for, so it fits whatever the graph is called.
        v_name  text := 'drivine_find_' || md5('ftrank' || ' ' || p_key || ' ' || p_labels::text);
        v_nid   bigint;
        v_row   ftrank_node;
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_name) THEN
            -- Each label is a test of its own, as a statement writes it, so a partial index over one is used.
            EXECUTE format('PREPARE %I (text) AS SELECT min(n.nid) FROM ftrank_node n WHERE (n.props ->> %L) = $1', v_name, p_key) ||
                COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(p_labels) l), '');
        END IF;
        LOOP
            EXECUTE format('EXECUTE %I(%L)', v_name, p_id) INTO v_nid;
            IF v_nid IS NULL THEN
                RETURN NULL;
            END IF;
            SELECT * INTO v_row FROM ftrank_node n WHERE n.nid = v_nid FOR UPDATE;
            -- Locked: is it still the node that was looked for? Another writer may have changed it meanwhile.
            IF FOUND AND v_row.props ->> p_key = p_id AND v_row.labels @> p_labels THEN
                RETURN v_row;
            END IF;
        END LOOP;
    END
    $fn$ LANGUAGE plpgsql;
    CREATE OR REPLACE FUNCTION ftrank_owns(p_bag jsonb, p_key text) RETURNS boolean AS $fn$
    DECLARE
        v_prefix   text := p_bag ->> 'prefix';
        v_reserved text;
    BEGIN
        -- A bag with a prefix owns the keys that begin with it; a flat bag, each key that is no one else's.
        IF NOT COALESCE((p_bag ->> 'flat')::boolean, false) THEN
            RETURN length(p_key) > COALESCE(length(v_prefix), 0) AND (v_prefix IS NULL OR left(p_key, length(v_prefix)) = v_prefix);
        END IF;
        IF COALESCE(p_bag -> 'reservedKeys', '[]'::jsonb) @> to_jsonb(p_key) THEN
            RETURN false;
        END IF;
        FOR v_reserved IN SELECT jsonb_array_elements_text(COALESCE(p_bag -> 'reservedPrefixes', '[]'::jsonb)) LOOP
            IF left(p_key, length(v_reserved)) = v_reserved THEN
                RETURN false;
            END IF;
        END LOOP;
        RETURN true;
    END
    $fn$ LANGUAGE plpgsql IMMUTABLE;
    CREATE OR REPLACE FUNCTION ftrank_lowered(p_props jsonb, p_keys jsonb) RETURNS jsonb AS $fn$
    DECLARE
        v_props jsonb := p_props;
        v_key   text;
    BEGIN
        FOR v_key IN SELECT jsonb_array_elements_text(COALESCE(p_keys, '[]'::jsonb)) LOOP
            IF v_props ->> v_key IS NULL THEN
                v_props := v_props - ('__drivine.lower.' || v_key);
            ELSE
                v_props := v_props || jsonb_build_object('__drivine.lower.' || v_key, lower(v_props ->> v_key));
            END IF;
        END LOOP;
        RETURN v_props;
    END
    $fn$ LANGUAGE plpgsql STABLE;
    CREATE OR REPLACE FUNCTION ftrank_write(p_plan jsonb, p_shapes jsonb, p_mark text, p_returns text, p_patched_if text) RETURNS SETOF text AS $fn$
    DECLARE
        v_op        jsonb;
        v_shape     jsonb;
        v_nodes     bigint[] := '{}';
        v_h_index   text[] := '{}';
        v_h_found   text[] := '{}';
        v_h_node    bigint[] := '{}';
        v_relinks   bigint[] := '{}';
        v_root      bigint;
        v_root_made boolean := false;
        v_was       text;
        v_carried   text;
        v_stamp     text;
        v_count     bigint := 0;
        v_result    text;
        v_each      text[] := '{}';
        v_stale     boolean := false;
        -- A node step's.
        v_row       ftrank_node;
        v_nid       bigint;
        v_found     text;
        v_two       text;
        v_labels    jsonb;
        v_o         jsonb;
        v_expect    text;
        v_fresh     text;
        v_add       jsonb;
        v_drop      jsonb;
        v_made      boolean;
        v_tries     int;
        v_relabel   boolean;
        v_bag       jsonb;
        v_key       text;
        v_owned     jsonb;
        v_recorded  jsonb;
        v_now       jsonb;
        v_same      boolean;
        v_copied    jsonb;
        v_met       bigint;
        v_premade   jsonb := '{}';
        v_after     jsonb;
        v_pre       bigint;
        v_s         int;
        v_premade_as text;
        -- A relationship step's.
        v_from      bigint;
        v_to        bigint;
        v_type      text;
        v_dir       text;
        v_props     jsonb;
        v_clear     jsonb;
        v_e         record;
        v_x         jsonb;
        v_seen      int;
        v_unchanged int;
        v_ids       jsonb;
        v_held      jsonb;
        v_keep      boolean;
        v_delete    boolean;
        v_gone      bigint[];
        v_targets   bigint[];
        v_keys      text[];
        v_target    bigint;
        v_refs      bigint;
        v_removed   bigint;
    BEGIN
        BEGIN
            -- The nodes the plan makes, made together. A `node` step that does no more than write properties,
            -- with no stamp to check, no property bag to clear and no labels to own, makes its node by an
            -- insert alone when the node is not there; so for each shape the nodes of such steps that are not
            -- there are found by one lookup and inserted by one statement, the first step for each id only. A
            -- node a uniqueness constraint refuses, made by another writer at this moment, is not inserted
            -- here: its step finds it, or is refused, as it would be on its own. What each made gets is in
            -- `v_premade`, by shape and id, for its step to take below.
            -- Only where a shape has several such steps: for one node, the lookup and insert of its step are as cheap.
            FOR v_s IN
                SELECT (op ->> 's')::int FROM jsonb_array_elements(p_plan) op
                WHERE op ->> 'op' = 'node' AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                GROUP BY 1 HAVING count(*) > 1
            LOOP
                v_shape := p_shapes -> v_s;
                -- Prepared once a session for the shape, as a lookup is, and run by name after: planned afresh,
                -- it costs more than it saves a save of a few nodes. The name holds the store's version too, so
                -- a session that outlives an upgrade does not run what an earlier version prepared.
                v_premade_as := 'drivine_made_' || md5('drivine:7 ftrank' || ' ' || (v_shape ->> 'key') || ' ' || (v_shape -> 'labels')::text);
                IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_premade_as) THEN
                    EXECUTE format('PREPARE %I (jsonb, int) AS ', v_premade_as) || format($made$
                        WITH steps AS (
                            SELECT DISTINCT ON (op ->> 'k') ord, op FROM jsonb_array_elements($1) WITH ORDINALITY AS t (op, ord)
                            WHERE op ->> 'op' = 'node' AND (op ->> 's')::int = $2 AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                            ORDER BY op ->> 'k', ord),
                        absent AS (
                            SELECT s.ord, s.op FROM steps s
                            WHERE NOT EXISTS (SELECT 1 FROM ftrank_node n WHERE (n.props ->> %L) = s.op ->> 'k'%s)),
                        made AS (
                            INSERT INTO ftrank_node (labels, props, stamp)
                            SELECT op -> 'labels',
                                   ftrank_lowered((jsonb_build_object(op ->> 'key', op -> 'id') || COALESCE(op -> 'set', '{}'::jsonb))
                                       - ARRAY(SELECT jsonb_array_elements_text(COALESCE(op -> 'unset', '[]'::jsonb))), op -> 'lower'),
                                   op ->> 'fresh'
                            FROM absent ORDER BY ord
                            ON CONFLICT DO NOTHING
                            RETURNING nid, props ->> %L AS k)
                        SELECT COALESCE(jsonb_object_agg(k, nid), '{}'::jsonb) FROM made
                    $made$, v_shape ->> 'key',
                        COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(v_shape -> 'labels') l), ''),
                        v_shape ->> 'key');
                END IF;
                EXECUTE format('EXECUTE %I(%L, %s)', v_premade_as, p_plan, v_s) INTO v_after;
                v_premade := v_premade || jsonb_build_object(v_s::text, v_after);
            END LOOP;

            FOR v_op IN SELECT value FROM jsonb_array_elements(p_plan) LOOP
                CASE v_op ->> 'op'
                WHEN 'node' THEN
                    -- Saves a node: found and locked, or made. What the step writes is worked out over the node as
                    -- it was found, and the node is written only where that differs from what it holds.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_expect := v_op ->> 'expect';
                    v_fresh := v_op ->> 'fresh';
                    v_tries := 0;
                    -- A node made with the others above is this step's, once: a later step for the same id finds it.
                    v_pre := (v_premade -> (v_op ->> 's') ->> (v_op ->> 'k'))::bigint;
                    IF v_pre IS NOT NULL THEN
                        v_premade := v_premade #- ARRAY[v_op ->> 's', v_op ->> 'k'];
                        v_nid := v_pre;
                        v_made := true;
                        v_found := NULL;
                    END IF;
                    WHILE v_pre IS NULL LOOP
                        v_row := ftrank_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                        v_made := v_row.nid IS NULL;
                        IF v_made THEN
                            -- A checked save does not make the node again: it is gone, and the object is stale.
                            -- Nor does a step that makes no node.
                            IF v_expect IS NOT NULL OR NOT COALESCE((v_op ->> 'create')::boolean, true) THEN
                                RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                            END IF;
                            v_labels := v_op -> 'labels';
                            v_o := jsonb_build_object(v_op ->> 'key', v_op -> 'id');
                            v_stamp := NULL;
                        ELSIF COALESCE((v_op ->> 'absent')::boolean, false) THEN
                            -- A step that only makes the node writes nothing to one that is there.
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        ELSE
                            v_labels := v_row.labels;
                            v_o := v_row.props;
                            v_stamp := v_row.stamp;
                        END IF;
                        v_found := v_stamp;
                        IF v_expect IS NOT NULL AND (v_stamp IS NULL OR
                                CASE WHEN COALESCE((v_op ->> 'whole')::boolean, false) THEN v_stamp ELSE substr(v_stamp, 1, 16) END <> v_expect) THEN
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        END IF;

                        -- The properties the step sets, and without those it unsets.
                        v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        -- The keys of each property bag the object no longer holds.
                        FOR v_bag IN SELECT value FROM jsonb_array_elements(COALESCE(v_op -> 'bags', '[]'::jsonb)) LOOP
                            FOR v_key IN SELECT jsonb_object_keys(v_o) LOOP
                                IF NOT COALESCE(v_bag -> 'keep', '[]'::jsonb) @> to_jsonb(v_key) AND ftrank_owns(v_bag, v_key) THEN
                                    v_o := v_o - v_key;
                                END IF;
                            END LOOP;
                        END LOOP;

                        -- The labels an open label field holds are recorded on the node, so the node knows which are
                        -- its own. A step that clears replaces the record, and drops the labels recorded that the
                        -- field no longer holds, but for those of the class; one that does not adds to the record.
                        v_add := COALESCE(v_op -> 'add', '[]'::jsonb);
                        v_drop := COALESCE(v_op -> 'drop', '[]'::jsonb);
                        v_owned := v_op -> 'owned';
                        IF v_owned IS NOT NULL THEN
                            v_recorded := v_o -> (v_owned ->> 'prop');
                            IF v_recorded IS NULL OR jsonb_typeof(v_recorded) <> 'array' THEN
                                v_recorded := '[]'::jsonb;
                            END IF;
                            IF COALESCE((v_owned ->> 'clear')::boolean, false) THEN
                                v_drop := v_drop || COALESCE((
                                    SELECT jsonb_agg(l) FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l) AND NOT COALESCE(v_owned -> 'base', '[]'::jsonb) @> to_jsonb(l)), '[]'::jsonb);
                                IF jsonb_array_length(v_add) = 0 THEN
                                    v_o := v_o - (v_owned ->> 'prop');
                                ELSE
                                    v_o := v_o || jsonb_build_object(v_owned ->> 'prop', v_add);
                                END IF;
                            ELSIF jsonb_array_length(v_add) > 0 THEN
                                v_o := v_o || jsonb_build_object(v_owned ->> 'prop', COALESCE((
                                    SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l)), '[]'::jsonb) || v_add);
                            END IF;
                        END IF;

                        -- The node's labels with those the step adds and without those it drops, in order; labels
                        -- that are as they were are not written again.
                        v_relabel := false;
                        IF jsonb_array_length(v_add) > 0 OR jsonb_array_length(v_drop) > 0 THEN
                            v_now := COALESCE((
                                SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM (
                                    SELECT jsonb_array_elements_text(v_labels) AS l UNION SELECT jsonb_array_elements_text(v_add)
                                ) a WHERE NOT v_drop @> to_jsonb(l)), '[]'::jsonb);
                            v_relabel := NOT (v_now @> v_labels AND v_labels @> v_now);
                            IF v_relabel OR v_made THEN
                                v_labels := v_now;
                            END IF;
                        END IF;

                        -- The copies are written from what the step leaves, and are no part of whether it changed the node.
                        v_copied := ftrank_lowered(v_o, v_op -> 'lower');
                        IF v_made THEN
                            -- A node that is made is written once, whole, with a stamp of its own. A uniqueness
                            -- constraint may refuse it: once, it may be that another writer made the node at this
                            -- moment, and the node is looked for again. Found again or not, the constraint is on
                            -- something other than this node's key, and refuses this save.
                            v_stamp := v_fresh;
                            INSERT INTO ftrank_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp) ON CONFLICT DO NOTHING RETURNING nid INTO v_nid;
                            IF v_nid IS NOT NULL THEN
                                EXIT;
                            END IF;
                            v_tries := v_tries + 1;
                            IF v_tries > 1 THEN
                                INSERT INTO ftrank_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp);
                            END IF;
                        ELSE
                            v_nid := v_row.nid;
                            v_same := v_o = v_row.props;
                            -- A new first token only if the step changes the node, or the node has no stamp of two tokens yet.
                            v_two := CASE WHEN length(v_stamp) = 33 AND substr(v_stamp, 17, 1) = ':' THEN v_stamp END;
                            IF v_two IS NULL OR NOT v_same OR v_relabel THEN
                                v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                                IF v_relabel THEN
                                    UPDATE ftrank_node SET labels = v_labels WHERE nid = v_nid;
                                END IF;
                                IF v_copied <> v_row.props THEN
                                    UPDATE ftrank_node SET props = v_copied, stamp = v_stamp WHERE nid = v_nid;
                                ELSE
                                    UPDATE ftrank_node SET stamp = v_stamp WHERE nid = v_nid;
                                END IF;
                            ELSIF v_copied <> v_row.props THEN
                                -- Only a copy was out of step with its property: the node keeps its stamp.
                                UPDATE ftrank_node SET props = v_copied WHERE nid = v_nid;
                            END IF;
                            EXIT;
                        END IF;
                    END LOOP;

                    v_nodes[(v_op ->> 'r')::int + 1] := v_nid;
                    IF v_op ->> 'i' IS NOT NULL THEN
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        -- Nothing for a node the step made, and a mark for one that was there without a stamp.
                        v_h_found := array_append(v_h_found, CASE WHEN v_made THEN NULL ELSE COALESCE(v_found, '-') END);
                        v_h_node := array_append(v_h_node, v_nid);
                    END IF;
                    IF COALESCE((v_op ->> 'root')::boolean, false) THEN
                        v_root := v_nid;
                        v_root_made := v_made;
                        v_was := v_found;
                        v_carried := v_op ->> 'carried';
                    END IF;

                WHEN 'ref' THEN
                    -- Finds a node that must be there, and locks it.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_row := ftrank_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NULL THEN
                        RAISE EXCEPTION 'absent' USING ERRCODE = 'P0D02';
                    END IF;
                    v_nodes[(v_op ->> 'r')::int + 1] := v_row.nid;

                WHEN 'link' THEN
                    -- Joins two nodes. The relationship is as the step says only if every one of its type between them is.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := v_nodes[(v_op ->> 'to')::int + 1];
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_props := COALESCE(v_op -> 'props', '{}'::jsonb);
                    v_clear := COALESCE(v_op -> 'clear', '[]'::jsonb);
                    v_seen := 0;
                    v_unchanged := 0;
                    IF NOT COALESCE((v_op ->> 'always')::boolean, false) THEN
                        -- A node's relationship to itself is one relationship, whichever way it is read.
                        FOR v_e IN
                            SELECT eid, props FROM ftrank_edge
                            WHERE type = v_type AND (
                                (v_dir IN ('OUT', 'BOTH') AND src = v_from AND dst = v_to)
                                OR ((v_dir = 'IN' OR (v_dir = 'BOTH' AND v_from <> v_to)) AND src = v_to AND dst = v_from))
                            ORDER BY eid
                        LOOP
                            v_seen := v_seen + 1;
                            v_x := (v_e.props || v_props) - ARRAY(SELECT jsonb_array_elements_text(v_clear));
                            IF v_x = v_e.props THEN
                                v_unchanged := v_unchanged + 1;
                            ELSE
                                UPDATE ftrank_edge SET props = v_x WHERE eid = v_e.eid;
                            END IF;
                        END LOOP;
                    END IF;
                    IF v_seen = 0 THEN
                        -- An undirected field is satisfied by a relationship either way, and makes one from the first node.
                        INSERT INTO ftrank_edge (src, dst, type, props)
                        VALUES (CASE WHEN v_dir = 'IN' THEN v_to ELSE v_from END, CASE WHEN v_dir = 'IN' THEN v_from ELSE v_to END, v_type, v_props);
                    END IF;
                    IF v_seen = 0 OR v_unchanged < v_seen THEN
                        v_relinks := v_relinks || v_from || v_to;
                    END IF;
                    v_count := v_count + GREATEST(v_seen, 1);

                WHEN 'unlink' THEN
                    -- Removes a field's relationships to the targets whose ids the step names, or to every target but those.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_ids := COALESCE(v_op -> 'ids', '[]'::jsonb);
                    v_held := COALESCE(v_op -> 'held', '[]'::jsonb);
                    v_keep := COALESCE((v_op ->> 'keep')::boolean, false);
                    v_delete := COALESCE((v_op ->> 'delete')::boolean, false);
                    v_gone := '{}';
                    v_targets := '{}';
                    v_keys := '{}';
                    -- A relationship from the node to itself is read as leaving it, and so once when both directions are read.
                    FOR v_e IN
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key') AS key
                        FROM ftrank_edge e JOIN ftrank_node t ON t.nid = e.dst
                        WHERE v_dir IN ('OUT', 'BOTH') AND e.src = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                        UNION ALL
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key')
                        FROM ftrank_edge e JOIN ftrank_node t ON t.nid = e.src
                        WHERE v_dir IN ('IN', 'BOTH') AND e.dst = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                          AND (v_dir = 'IN' OR e.src <> v_from)
                    LOOP
                        IF v_e.key IS NOT NULL AND (v_ids @> to_jsonb(v_e.key)) <> v_keep THEN
                            v_gone := array_append(v_gone, v_e.eid);
                            v_targets := array_append(v_targets, v_e.nid);
                            v_keys := array_append(v_keys, v_e.key);
                        END IF;
                    END LOOP;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- A target gone since the relationships were read has nothing left to remove or count.
                            PERFORM 1 FROM ftrank_node WHERE nid = v_target FOR UPDATE;
                            IF NOT FOUND THEN
                                CONTINUE;
                            END IF;
                            -- What refers to a target is a relationship on the side this field reaches it from: counted before any is removed.
                            v_refs := 0;
                            IF v_delete THEN
                                IF v_dir IN ('OUT', 'BOTH') THEN
                                    SELECT count(*) INTO v_refs FROM ftrank_edge WHERE dst = v_target;
                                END IF;
                                IF v_dir IN ('IN', 'BOTH') THEN
                                    -- A relationship from the node to itself is counted once.
                                    SELECT v_refs + count(*) INTO v_refs FROM ftrank_edge WHERE src = v_target AND (v_dir = 'IN' OR dst <> v_target);
                                END IF;
                            END IF;
                            SELECT count(*) INTO v_removed FROM unnest(v_targets) t WHERE t = v_target;
                            SELECT k INTO v_key FROM unnest(v_targets, v_keys) AS u (t, k) WHERE t = v_target LIMIT 1;
                            -- The root is never deleted, and nor is a node the object still holds in another field.
                            IF v_delete AND v_target <> v_from AND v_refs = v_removed AND NOT v_held @> to_jsonb(v_key) THEN
                                v_relinks := array_remove(v_relinks, v_target);
                                DELETE FROM ftrank_node WHERE nid = v_target;
                            ELSE
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM ftrank_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'cut' THEN
                    -- Removes the relationships of a type from one node to another, or with no other node named to any in a direction.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := CASE WHEN v_op ->> 'to' IS NOT NULL THEN v_nodes[(v_op ->> 'to')::int + 1] END;
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    SELECT COALESCE(array_agg(c.eid), '{}'), COALESCE(array_agg(c.far), '{}') INTO v_gone, v_targets FROM (
                        SELECT eid, dst AS far FROM ftrank_edge
                        WHERE v_dir IN ('OUT', 'BOTH') AND src = v_from AND type = v_type AND (v_to IS NULL OR dst = v_to)
                        UNION ALL
                        SELECT eid, src FROM ftrank_edge
                        WHERE v_dir IN ('IN', 'BOTH') AND dst = v_from AND type = v_type AND (v_to IS NULL OR src = v_to) AND (v_dir = 'IN' OR src <> v_from)
                    ) c;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- An end gone since the relationships were read took them with it, and has no token to change.
                            PERFORM 1 FROM ftrank_node WHERE nid = v_target FOR UPDATE;
                            IF FOUND THEN
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM ftrank_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'patch' THEN
                    -- Writes properties to a node that is there, and makes none. One that is not there is left out of
                    -- what the call hands back; one that does not meet the predicate is left as it is, and said to.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_fresh := v_op ->> 'fresh';
                    v_row := ftrank_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NOT NULL THEN
                        v_met := 1;
                        IF p_patched_if IS NOT NULL THEN
                            -- The node is locked: what the predicate reads of it is what the last writer committed.
                            EXECUTE p_patched_if INTO v_met USING v_row.nid;
                        END IF;
                        v_o := v_row.props;
                        IF v_met > 0 THEN
                            v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        END IF;
                        v_same := v_o = v_row.props;
                        -- A node the step changes has its copies written from what it now holds.
                        IF NOT v_same THEN
                            v_o := ftrank_lowered(v_o, v_op -> 'lower');
                        END IF;
                        v_two := CASE WHEN length(v_row.stamp) = 33 AND substr(v_row.stamp, 17, 1) = ':' THEN v_row.stamp END;
                        IF v_two IS NULL OR NOT v_same THEN
                            v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                            IF NOT v_same THEN
                                UPDATE ftrank_node SET props = v_o, stamp = v_stamp WHERE nid = v_row.nid;
                            ELSE
                                UPDATE ftrank_node SET stamp = v_stamp WHERE nid = v_row.nid;
                            END IF;
                        END IF;
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        v_h_found := array_append(v_h_found, CASE WHEN v_met = 0 THEN '-' WHEN NOT v_same THEN '1' ELSE '0' END);
                        v_h_node := array_append(v_h_node, v_row.nid);
                    END IF;
                END CASE;
            END LOOP;

            -- Each node whose relationships changed gets a new second token, once. Every one of them is locked
            -- already, found and locked by its step or made by it, so one statement writes them all and waits
            -- for no lock. A stamp that is not two tokens, which no save leaves, is replaced whole.
            IF cardinality(v_relinks) > 0 THEN
                UPDATE ftrank_node SET stamp = COALESCE(substr(CASE WHEN length(stamp) = 33 AND substr(stamp, 17, 1) = ':' THEN stamp END, 1, 17), substr(p_mark, 1, 17)) || substr(p_mark, 18)
                WHERE nid = ANY (v_relinks);
            END IF;

            IF p_returns = 'STAMPS' THEN
                -- The root's stamp, keeping the object's own token wherever the node had another when the save
                -- began, then `index/found=stamp` for each node whose stamp is handed back.
                SELECT stamp INTO v_stamp FROM ftrank_node WHERE nid = v_root;
                IF v_carried IS NULL THEN
                    -- An object that carried no stamp is handed the whole stamp only of a node its save made.
                    IF NOT v_root_made THEN
                        v_stamp := substr(v_stamp, 1, 17);
                    END IF;
                ELSIF v_was = v_carried THEN
                    NULL; -- found exactly as loaded: the node's stamp is handed back whole
                ELSE
                    v_stamp := CASE WHEN substr(v_was, 1, 16) = substr(v_carried, 1, 16) THEN substr(v_stamp, 1, 16) ELSE substr(v_carried, 1, 16) END || ':' ||
                        CASE WHEN NULLIF(substr(v_was, 18), '') = NULLIF(substr(v_carried, 18), '') OR (v_root_made AND NULLIF(substr(v_carried, 18), '') IS NULL)
                             THEN substr(v_stamp, 18) ELSE substr(v_carried, 18) END;
                END IF;
                -- Every handed-back stamp is read by one query, in the order the steps came.
                SELECT v_stamp || COALESCE(string_agg(',' || h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, ''), '' ORDER BY h.ord), '')
                INTO v_result
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN ftrank_node n ON n.nid = h.nid;
            ELSIF p_returns = 'EACH_STAMP' THEN
                SELECT COALESCE(array_agg(h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, '') ORDER BY h.ord), '{}')
                INTO v_each
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN ftrank_node n ON n.nid = h.nid;
            END IF;
        EXCEPTION
            WHEN SQLSTATE 'P0D01' THEN v_stale := true; -- rolled back: nothing was written
            WHEN SQLSTATE 'P0D02' THEN v_count := 0;   -- a node the plan refers to is not there: rolled back, nothing was written
        END;
        IF p_returns = 'STAMPS' THEN
            IF NOT v_stale AND v_result IS NOT NULL THEN
                RETURN NEXT v_result;
            END IF;
        ELSIF p_returns = 'EACH_STAMP' THEN
            IF NOT v_stale THEN
                RETURN QUERY SELECT unnest(v_each);
            END IF;
        ELSE
            RETURN NEXT v_count::text;
        END IF;
    END
    $fn$ LANGUAGE plpgsql;
    COMMENT ON TABLE ftrank_node IS 'drivine:7';
        END IF;
    END IF;
END
$ensure$

DO $ensure$
BEGIN
    IF obj_description(to_regclass('ftranki_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
        PERFORM pg_advisory_xact_lock(hashtext('drivine:ftranki'));
        -- Looked for again under the lock: another session may have made it while this one waited.
        IF obj_description(to_regclass('ftranki_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
            -- pgvector, for vector search, where the server has it and the user may make it: without it,
            -- everything but a vector search works.
            BEGIN
                CREATE EXTENSION IF NOT EXISTS vector;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            CREATE TABLE IF NOT EXISTS ftranki_node (
        nid    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        labels jsonb NOT NULL,
        props  jsonb NOT NULL,
        stamp  varchar(33)
    );
    CREATE TABLE IF NOT EXISTS ftranki_edge (
        eid   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        src   bigint NOT NULL REFERENCES ftranki_node (nid) ON DELETE CASCADE,
        dst   bigint NOT NULL REFERENCES ftranki_node (nid) ON DELETE CASCADE,
        type  varchar(128) NOT NULL,
        props jsonb NOT NULL DEFAULT '{}'
    );
    CREATE TABLE IF NOT EXISTS ftranki_schema (
        kind        varchar(40) NOT NULL,
        label       varchar(400) NOT NULL,
        properties  varchar(2000) NOT NULL,
        name        varchar(400),
        object_name varchar(63),
        details     jsonb NOT NULL,
        PRIMARY KEY (kind, label, properties)
    );
    CREATE INDEX IF NOT EXISTS ftranki_edge_src ON ftranki_edge (src, type);
    CREATE INDEX IF NOT EXISTS ftranki_edge_dst ON ftranki_edge (dst, type);
    CREATE INDEX IF NOT EXISTS ftranki_node_labels ON ftranki_node USING GIN (labels jsonb_path_ops);
    CREATE OR REPLACE FUNCTION ftranki_find(p_labels jsonb, p_key text, p_id text) RETURNS ftranki_node AS $fn$
    DECLARE
        -- The lookup of a shape is prepared once a session and run by name after: written for the shape, it
        -- is planned for its label and property, and planned again each time it would cost a lookup several
        -- times over. The name is a hash of what the lookup is for, so it fits whatever the graph is called.
        v_name  text := 'drivine_find_' || md5('ftranki' || ' ' || p_key || ' ' || p_labels::text);
        v_nid   bigint;
        v_row   ftranki_node;
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_name) THEN
            -- Each label is a test of its own, as a statement writes it, so a partial index over one is used.
            EXECUTE format('PREPARE %I (text) AS SELECT min(n.nid) FROM ftranki_node n WHERE (n.props ->> %L) = $1', v_name, p_key) ||
                COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(p_labels) l), '');
        END IF;
        LOOP
            EXECUTE format('EXECUTE %I(%L)', v_name, p_id) INTO v_nid;
            IF v_nid IS NULL THEN
                RETURN NULL;
            END IF;
            SELECT * INTO v_row FROM ftranki_node n WHERE n.nid = v_nid FOR UPDATE;
            -- Locked: is it still the node that was looked for? Another writer may have changed it meanwhile.
            IF FOUND AND v_row.props ->> p_key = p_id AND v_row.labels @> p_labels THEN
                RETURN v_row;
            END IF;
        END LOOP;
    END
    $fn$ LANGUAGE plpgsql;
    CREATE OR REPLACE FUNCTION ftranki_owns(p_bag jsonb, p_key text) RETURNS boolean AS $fn$
    DECLARE
        v_prefix   text := p_bag ->> 'prefix';
        v_reserved text;
    BEGIN
        -- A bag with a prefix owns the keys that begin with it; a flat bag, each key that is no one else's.
        IF NOT COALESCE((p_bag ->> 'flat')::boolean, false) THEN
            RETURN length(p_key) > COALESCE(length(v_prefix), 0) AND (v_prefix IS NULL OR left(p_key, length(v_prefix)) = v_prefix);
        END IF;
        IF COALESCE(p_bag -> 'reservedKeys', '[]'::jsonb) @> to_jsonb(p_key) THEN
            RETURN false;
        END IF;
        FOR v_reserved IN SELECT jsonb_array_elements_text(COALESCE(p_bag -> 'reservedPrefixes', '[]'::jsonb)) LOOP
            IF left(p_key, length(v_reserved)) = v_reserved THEN
                RETURN false;
            END IF;
        END LOOP;
        RETURN true;
    END
    $fn$ LANGUAGE plpgsql IMMUTABLE;
    CREATE OR REPLACE FUNCTION ftranki_lowered(p_props jsonb, p_keys jsonb) RETURNS jsonb AS $fn$
    DECLARE
        v_props jsonb := p_props;
        v_key   text;
    BEGIN
        FOR v_key IN SELECT jsonb_array_elements_text(COALESCE(p_keys, '[]'::jsonb)) LOOP
            IF v_props ->> v_key IS NULL THEN
                v_props := v_props - ('__drivine.lower.' || v_key);
            ELSE
                v_props := v_props || jsonb_build_object('__drivine.lower.' || v_key, lower(v_props ->> v_key));
            END IF;
        END LOOP;
        RETURN v_props;
    END
    $fn$ LANGUAGE plpgsql STABLE;
    CREATE OR REPLACE FUNCTION ftranki_write(p_plan jsonb, p_shapes jsonb, p_mark text, p_returns text, p_patched_if text) RETURNS SETOF text AS $fn$
    DECLARE
        v_op        jsonb;
        v_shape     jsonb;
        v_nodes     bigint[] := '{}';
        v_h_index   text[] := '{}';
        v_h_found   text[] := '{}';
        v_h_node    bigint[] := '{}';
        v_relinks   bigint[] := '{}';
        v_root      bigint;
        v_root_made boolean := false;
        v_was       text;
        v_carried   text;
        v_stamp     text;
        v_count     bigint := 0;
        v_result    text;
        v_each      text[] := '{}';
        v_stale     boolean := false;
        -- A node step's.
        v_row       ftranki_node;
        v_nid       bigint;
        v_found     text;
        v_two       text;
        v_labels    jsonb;
        v_o         jsonb;
        v_expect    text;
        v_fresh     text;
        v_add       jsonb;
        v_drop      jsonb;
        v_made      boolean;
        v_tries     int;
        v_relabel   boolean;
        v_bag       jsonb;
        v_key       text;
        v_owned     jsonb;
        v_recorded  jsonb;
        v_now       jsonb;
        v_same      boolean;
        v_copied    jsonb;
        v_met       bigint;
        v_premade   jsonb := '{}';
        v_after     jsonb;
        v_pre       bigint;
        v_s         int;
        v_premade_as text;
        -- A relationship step's.
        v_from      bigint;
        v_to        bigint;
        v_type      text;
        v_dir       text;
        v_props     jsonb;
        v_clear     jsonb;
        v_e         record;
        v_x         jsonb;
        v_seen      int;
        v_unchanged int;
        v_ids       jsonb;
        v_held      jsonb;
        v_keep      boolean;
        v_delete    boolean;
        v_gone      bigint[];
        v_targets   bigint[];
        v_keys      text[];
        v_target    bigint;
        v_refs      bigint;
        v_removed   bigint;
    BEGIN
        BEGIN
            -- The nodes the plan makes, made together. A `node` step that does no more than write properties,
            -- with no stamp to check, no property bag to clear and no labels to own, makes its node by an
            -- insert alone when the node is not there; so for each shape the nodes of such steps that are not
            -- there are found by one lookup and inserted by one statement, the first step for each id only. A
            -- node a uniqueness constraint refuses, made by another writer at this moment, is not inserted
            -- here: its step finds it, or is refused, as it would be on its own. What each made gets is in
            -- `v_premade`, by shape and id, for its step to take below.
            -- Only where a shape has several such steps: for one node, the lookup and insert of its step are as cheap.
            FOR v_s IN
                SELECT (op ->> 's')::int FROM jsonb_array_elements(p_plan) op
                WHERE op ->> 'op' = 'node' AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                GROUP BY 1 HAVING count(*) > 1
            LOOP
                v_shape := p_shapes -> v_s;
                -- Prepared once a session for the shape, as a lookup is, and run by name after: planned afresh,
                -- it costs more than it saves a save of a few nodes. The name holds the store's version too, so
                -- a session that outlives an upgrade does not run what an earlier version prepared.
                v_premade_as := 'drivine_made_' || md5('drivine:7 ftranki' || ' ' || (v_shape ->> 'key') || ' ' || (v_shape -> 'labels')::text);
                IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_premade_as) THEN
                    EXECUTE format('PREPARE %I (jsonb, int) AS ', v_premade_as) || format($made$
                        WITH steps AS (
                            SELECT DISTINCT ON (op ->> 'k') ord, op FROM jsonb_array_elements($1) WITH ORDINALITY AS t (op, ord)
                            WHERE op ->> 'op' = 'node' AND (op ->> 's')::int = $2 AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                            ORDER BY op ->> 'k', ord),
                        absent AS (
                            SELECT s.ord, s.op FROM steps s
                            WHERE NOT EXISTS (SELECT 1 FROM ftranki_node n WHERE (n.props ->> %L) = s.op ->> 'k'%s)),
                        made AS (
                            INSERT INTO ftranki_node (labels, props, stamp)
                            SELECT op -> 'labels',
                                   ftranki_lowered((jsonb_build_object(op ->> 'key', op -> 'id') || COALESCE(op -> 'set', '{}'::jsonb))
                                       - ARRAY(SELECT jsonb_array_elements_text(COALESCE(op -> 'unset', '[]'::jsonb))), op -> 'lower'),
                                   op ->> 'fresh'
                            FROM absent ORDER BY ord
                            ON CONFLICT DO NOTHING
                            RETURNING nid, props ->> %L AS k)
                        SELECT COALESCE(jsonb_object_agg(k, nid), '{}'::jsonb) FROM made
                    $made$, v_shape ->> 'key',
                        COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(v_shape -> 'labels') l), ''),
                        v_shape ->> 'key');
                END IF;
                EXECUTE format('EXECUTE %I(%L, %s)', v_premade_as, p_plan, v_s) INTO v_after;
                v_premade := v_premade || jsonb_build_object(v_s::text, v_after);
            END LOOP;

            FOR v_op IN SELECT value FROM jsonb_array_elements(p_plan) LOOP
                CASE v_op ->> 'op'
                WHEN 'node' THEN
                    -- Saves a node: found and locked, or made. What the step writes is worked out over the node as
                    -- it was found, and the node is written only where that differs from what it holds.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_expect := v_op ->> 'expect';
                    v_fresh := v_op ->> 'fresh';
                    v_tries := 0;
                    -- A node made with the others above is this step's, once: a later step for the same id finds it.
                    v_pre := (v_premade -> (v_op ->> 's') ->> (v_op ->> 'k'))::bigint;
                    IF v_pre IS NOT NULL THEN
                        v_premade := v_premade #- ARRAY[v_op ->> 's', v_op ->> 'k'];
                        v_nid := v_pre;
                        v_made := true;
                        v_found := NULL;
                    END IF;
                    WHILE v_pre IS NULL LOOP
                        v_row := ftranki_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                        v_made := v_row.nid IS NULL;
                        IF v_made THEN
                            -- A checked save does not make the node again: it is gone, and the object is stale.
                            -- Nor does a step that makes no node.
                            IF v_expect IS NOT NULL OR NOT COALESCE((v_op ->> 'create')::boolean, true) THEN
                                RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                            END IF;
                            v_labels := v_op -> 'labels';
                            v_o := jsonb_build_object(v_op ->> 'key', v_op -> 'id');
                            v_stamp := NULL;
                        ELSIF COALESCE((v_op ->> 'absent')::boolean, false) THEN
                            -- A step that only makes the node writes nothing to one that is there.
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        ELSE
                            v_labels := v_row.labels;
                            v_o := v_row.props;
                            v_stamp := v_row.stamp;
                        END IF;
                        v_found := v_stamp;
                        IF v_expect IS NOT NULL AND (v_stamp IS NULL OR
                                CASE WHEN COALESCE((v_op ->> 'whole')::boolean, false) THEN v_stamp ELSE substr(v_stamp, 1, 16) END <> v_expect) THEN
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        END IF;

                        -- The properties the step sets, and without those it unsets.
                        v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        -- The keys of each property bag the object no longer holds.
                        FOR v_bag IN SELECT value FROM jsonb_array_elements(COALESCE(v_op -> 'bags', '[]'::jsonb)) LOOP
                            FOR v_key IN SELECT jsonb_object_keys(v_o) LOOP
                                IF NOT COALESCE(v_bag -> 'keep', '[]'::jsonb) @> to_jsonb(v_key) AND ftranki_owns(v_bag, v_key) THEN
                                    v_o := v_o - v_key;
                                END IF;
                            END LOOP;
                        END LOOP;

                        -- The labels an open label field holds are recorded on the node, so the node knows which are
                        -- its own. A step that clears replaces the record, and drops the labels recorded that the
                        -- field no longer holds, but for those of the class; one that does not adds to the record.
                        v_add := COALESCE(v_op -> 'add', '[]'::jsonb);
                        v_drop := COALESCE(v_op -> 'drop', '[]'::jsonb);
                        v_owned := v_op -> 'owned';
                        IF v_owned IS NOT NULL THEN
                            v_recorded := v_o -> (v_owned ->> 'prop');
                            IF v_recorded IS NULL OR jsonb_typeof(v_recorded) <> 'array' THEN
                                v_recorded := '[]'::jsonb;
                            END IF;
                            IF COALESCE((v_owned ->> 'clear')::boolean, false) THEN
                                v_drop := v_drop || COALESCE((
                                    SELECT jsonb_agg(l) FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l) AND NOT COALESCE(v_owned -> 'base', '[]'::jsonb) @> to_jsonb(l)), '[]'::jsonb);
                                IF jsonb_array_length(v_add) = 0 THEN
                                    v_o := v_o - (v_owned ->> 'prop');
                                ELSE
                                    v_o := v_o || jsonb_build_object(v_owned ->> 'prop', v_add);
                                END IF;
                            ELSIF jsonb_array_length(v_add) > 0 THEN
                                v_o := v_o || jsonb_build_object(v_owned ->> 'prop', COALESCE((
                                    SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l)), '[]'::jsonb) || v_add);
                            END IF;
                        END IF;

                        -- The node's labels with those the step adds and without those it drops, in order; labels
                        -- that are as they were are not written again.
                        v_relabel := false;
                        IF jsonb_array_length(v_add) > 0 OR jsonb_array_length(v_drop) > 0 THEN
                            v_now := COALESCE((
                                SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM (
                                    SELECT jsonb_array_elements_text(v_labels) AS l UNION SELECT jsonb_array_elements_text(v_add)
                                ) a WHERE NOT v_drop @> to_jsonb(l)), '[]'::jsonb);
                            v_relabel := NOT (v_now @> v_labels AND v_labels @> v_now);
                            IF v_relabel OR v_made THEN
                                v_labels := v_now;
                            END IF;
                        END IF;

                        -- The copies are written from what the step leaves, and are no part of whether it changed the node.
                        v_copied := ftranki_lowered(v_o, v_op -> 'lower');
                        IF v_made THEN
                            -- A node that is made is written once, whole, with a stamp of its own. A uniqueness
                            -- constraint may refuse it: once, it may be that another writer made the node at this
                            -- moment, and the node is looked for again. Found again or not, the constraint is on
                            -- something other than this node's key, and refuses this save.
                            v_stamp := v_fresh;
                            INSERT INTO ftranki_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp) ON CONFLICT DO NOTHING RETURNING nid INTO v_nid;
                            IF v_nid IS NOT NULL THEN
                                EXIT;
                            END IF;
                            v_tries := v_tries + 1;
                            IF v_tries > 1 THEN
                                INSERT INTO ftranki_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp);
                            END IF;
                        ELSE
                            v_nid := v_row.nid;
                            v_same := v_o = v_row.props;
                            -- A new first token only if the step changes the node, or the node has no stamp of two tokens yet.
                            v_two := CASE WHEN length(v_stamp) = 33 AND substr(v_stamp, 17, 1) = ':' THEN v_stamp END;
                            IF v_two IS NULL OR NOT v_same OR v_relabel THEN
                                v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                                IF v_relabel THEN
                                    UPDATE ftranki_node SET labels = v_labels WHERE nid = v_nid;
                                END IF;
                                IF v_copied <> v_row.props THEN
                                    UPDATE ftranki_node SET props = v_copied, stamp = v_stamp WHERE nid = v_nid;
                                ELSE
                                    UPDATE ftranki_node SET stamp = v_stamp WHERE nid = v_nid;
                                END IF;
                            ELSIF v_copied <> v_row.props THEN
                                -- Only a copy was out of step with its property: the node keeps its stamp.
                                UPDATE ftranki_node SET props = v_copied WHERE nid = v_nid;
                            END IF;
                            EXIT;
                        END IF;
                    END LOOP;

                    v_nodes[(v_op ->> 'r')::int + 1] := v_nid;
                    IF v_op ->> 'i' IS NOT NULL THEN
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        -- Nothing for a node the step made, and a mark for one that was there without a stamp.
                        v_h_found := array_append(v_h_found, CASE WHEN v_made THEN NULL ELSE COALESCE(v_found, '-') END);
                        v_h_node := array_append(v_h_node, v_nid);
                    END IF;
                    IF COALESCE((v_op ->> 'root')::boolean, false) THEN
                        v_root := v_nid;
                        v_root_made := v_made;
                        v_was := v_found;
                        v_carried := v_op ->> 'carried';
                    END IF;

                WHEN 'ref' THEN
                    -- Finds a node that must be there, and locks it.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_row := ftranki_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NULL THEN
                        RAISE EXCEPTION 'absent' USING ERRCODE = 'P0D02';
                    END IF;
                    v_nodes[(v_op ->> 'r')::int + 1] := v_row.nid;

                WHEN 'link' THEN
                    -- Joins two nodes. The relationship is as the step says only if every one of its type between them is.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := v_nodes[(v_op ->> 'to')::int + 1];
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_props := COALESCE(v_op -> 'props', '{}'::jsonb);
                    v_clear := COALESCE(v_op -> 'clear', '[]'::jsonb);
                    v_seen := 0;
                    v_unchanged := 0;
                    IF NOT COALESCE((v_op ->> 'always')::boolean, false) THEN
                        -- A node's relationship to itself is one relationship, whichever way it is read.
                        FOR v_e IN
                            SELECT eid, props FROM ftranki_edge
                            WHERE type = v_type AND (
                                (v_dir IN ('OUT', 'BOTH') AND src = v_from AND dst = v_to)
                                OR ((v_dir = 'IN' OR (v_dir = 'BOTH' AND v_from <> v_to)) AND src = v_to AND dst = v_from))
                            ORDER BY eid
                        LOOP
                            v_seen := v_seen + 1;
                            v_x := (v_e.props || v_props) - ARRAY(SELECT jsonb_array_elements_text(v_clear));
                            IF v_x = v_e.props THEN
                                v_unchanged := v_unchanged + 1;
                            ELSE
                                UPDATE ftranki_edge SET props = v_x WHERE eid = v_e.eid;
                            END IF;
                        END LOOP;
                    END IF;
                    IF v_seen = 0 THEN
                        -- An undirected field is satisfied by a relationship either way, and makes one from the first node.
                        INSERT INTO ftranki_edge (src, dst, type, props)
                        VALUES (CASE WHEN v_dir = 'IN' THEN v_to ELSE v_from END, CASE WHEN v_dir = 'IN' THEN v_from ELSE v_to END, v_type, v_props);
                    END IF;
                    IF v_seen = 0 OR v_unchanged < v_seen THEN
                        v_relinks := v_relinks || v_from || v_to;
                    END IF;
                    v_count := v_count + GREATEST(v_seen, 1);

                WHEN 'unlink' THEN
                    -- Removes a field's relationships to the targets whose ids the step names, or to every target but those.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_ids := COALESCE(v_op -> 'ids', '[]'::jsonb);
                    v_held := COALESCE(v_op -> 'held', '[]'::jsonb);
                    v_keep := COALESCE((v_op ->> 'keep')::boolean, false);
                    v_delete := COALESCE((v_op ->> 'delete')::boolean, false);
                    v_gone := '{}';
                    v_targets := '{}';
                    v_keys := '{}';
                    -- A relationship from the node to itself is read as leaving it, and so once when both directions are read.
                    FOR v_e IN
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key') AS key
                        FROM ftranki_edge e JOIN ftranki_node t ON t.nid = e.dst
                        WHERE v_dir IN ('OUT', 'BOTH') AND e.src = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                        UNION ALL
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key')
                        FROM ftranki_edge e JOIN ftranki_node t ON t.nid = e.src
                        WHERE v_dir IN ('IN', 'BOTH') AND e.dst = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                          AND (v_dir = 'IN' OR e.src <> v_from)
                    LOOP
                        IF v_e.key IS NOT NULL AND (v_ids @> to_jsonb(v_e.key)) <> v_keep THEN
                            v_gone := array_append(v_gone, v_e.eid);
                            v_targets := array_append(v_targets, v_e.nid);
                            v_keys := array_append(v_keys, v_e.key);
                        END IF;
                    END LOOP;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- A target gone since the relationships were read has nothing left to remove or count.
                            PERFORM 1 FROM ftranki_node WHERE nid = v_target FOR UPDATE;
                            IF NOT FOUND THEN
                                CONTINUE;
                            END IF;
                            -- What refers to a target is a relationship on the side this field reaches it from: counted before any is removed.
                            v_refs := 0;
                            IF v_delete THEN
                                IF v_dir IN ('OUT', 'BOTH') THEN
                                    SELECT count(*) INTO v_refs FROM ftranki_edge WHERE dst = v_target;
                                END IF;
                                IF v_dir IN ('IN', 'BOTH') THEN
                                    -- A relationship from the node to itself is counted once.
                                    SELECT v_refs + count(*) INTO v_refs FROM ftranki_edge WHERE src = v_target AND (v_dir = 'IN' OR dst <> v_target);
                                END IF;
                            END IF;
                            SELECT count(*) INTO v_removed FROM unnest(v_targets) t WHERE t = v_target;
                            SELECT k INTO v_key FROM unnest(v_targets, v_keys) AS u (t, k) WHERE t = v_target LIMIT 1;
                            -- The root is never deleted, and nor is a node the object still holds in another field.
                            IF v_delete AND v_target <> v_from AND v_refs = v_removed AND NOT v_held @> to_jsonb(v_key) THEN
                                v_relinks := array_remove(v_relinks, v_target);
                                DELETE FROM ftranki_node WHERE nid = v_target;
                            ELSE
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM ftranki_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'cut' THEN
                    -- Removes the relationships of a type from one node to another, or with no other node named to any in a direction.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := CASE WHEN v_op ->> 'to' IS NOT NULL THEN v_nodes[(v_op ->> 'to')::int + 1] END;
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    SELECT COALESCE(array_agg(c.eid), '{}'), COALESCE(array_agg(c.far), '{}') INTO v_gone, v_targets FROM (
                        SELECT eid, dst AS far FROM ftranki_edge
                        WHERE v_dir IN ('OUT', 'BOTH') AND src = v_from AND type = v_type AND (v_to IS NULL OR dst = v_to)
                        UNION ALL
                        SELECT eid, src FROM ftranki_edge
                        WHERE v_dir IN ('IN', 'BOTH') AND dst = v_from AND type = v_type AND (v_to IS NULL OR src = v_to) AND (v_dir = 'IN' OR src <> v_from)
                    ) c;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- An end gone since the relationships were read took them with it, and has no token to change.
                            PERFORM 1 FROM ftranki_node WHERE nid = v_target FOR UPDATE;
                            IF FOUND THEN
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM ftranki_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'patch' THEN
                    -- Writes properties to a node that is there, and makes none. One that is not there is left out of
                    -- what the call hands back; one that does not meet the predicate is left as it is, and said to.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_fresh := v_op ->> 'fresh';
                    v_row := ftranki_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NOT NULL THEN
                        v_met := 1;
                        IF p_patched_if IS NOT NULL THEN
                            -- The node is locked: what the predicate reads of it is what the last writer committed.
                            EXECUTE p_patched_if INTO v_met USING v_row.nid;
                        END IF;
                        v_o := v_row.props;
                        IF v_met > 0 THEN
                            v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        END IF;
                        v_same := v_o = v_row.props;
                        -- A node the step changes has its copies written from what it now holds.
                        IF NOT v_same THEN
                            v_o := ftranki_lowered(v_o, v_op -> 'lower');
                        END IF;
                        v_two := CASE WHEN length(v_row.stamp) = 33 AND substr(v_row.stamp, 17, 1) = ':' THEN v_row.stamp END;
                        IF v_two IS NULL OR NOT v_same THEN
                            v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                            IF NOT v_same THEN
                                UPDATE ftranki_node SET props = v_o, stamp = v_stamp WHERE nid = v_row.nid;
                            ELSE
                                UPDATE ftranki_node SET stamp = v_stamp WHERE nid = v_row.nid;
                            END IF;
                        END IF;
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        v_h_found := array_append(v_h_found, CASE WHEN v_met = 0 THEN '-' WHEN NOT v_same THEN '1' ELSE '0' END);
                        v_h_node := array_append(v_h_node, v_row.nid);
                    END IF;
                END CASE;
            END LOOP;

            -- Each node whose relationships changed gets a new second token, once. Every one of them is locked
            -- already, found and locked by its step or made by it, so one statement writes them all and waits
            -- for no lock. A stamp that is not two tokens, which no save leaves, is replaced whole.
            IF cardinality(v_relinks) > 0 THEN
                UPDATE ftranki_node SET stamp = COALESCE(substr(CASE WHEN length(stamp) = 33 AND substr(stamp, 17, 1) = ':' THEN stamp END, 1, 17), substr(p_mark, 1, 17)) || substr(p_mark, 18)
                WHERE nid = ANY (v_relinks);
            END IF;

            IF p_returns = 'STAMPS' THEN
                -- The root's stamp, keeping the object's own token wherever the node had another when the save
                -- began, then `index/found=stamp` for each node whose stamp is handed back.
                SELECT stamp INTO v_stamp FROM ftranki_node WHERE nid = v_root;
                IF v_carried IS NULL THEN
                    -- An object that carried no stamp is handed the whole stamp only of a node its save made.
                    IF NOT v_root_made THEN
                        v_stamp := substr(v_stamp, 1, 17);
                    END IF;
                ELSIF v_was = v_carried THEN
                    NULL; -- found exactly as loaded: the node's stamp is handed back whole
                ELSE
                    v_stamp := CASE WHEN substr(v_was, 1, 16) = substr(v_carried, 1, 16) THEN substr(v_stamp, 1, 16) ELSE substr(v_carried, 1, 16) END || ':' ||
                        CASE WHEN NULLIF(substr(v_was, 18), '') = NULLIF(substr(v_carried, 18), '') OR (v_root_made AND NULLIF(substr(v_carried, 18), '') IS NULL)
                             THEN substr(v_stamp, 18) ELSE substr(v_carried, 18) END;
                END IF;
                -- Every handed-back stamp is read by one query, in the order the steps came.
                SELECT v_stamp || COALESCE(string_agg(',' || h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, ''), '' ORDER BY h.ord), '')
                INTO v_result
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN ftranki_node n ON n.nid = h.nid;
            ELSIF p_returns = 'EACH_STAMP' THEN
                SELECT COALESCE(array_agg(h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, '') ORDER BY h.ord), '{}')
                INTO v_each
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN ftranki_node n ON n.nid = h.nid;
            END IF;
        EXCEPTION
            WHEN SQLSTATE 'P0D01' THEN v_stale := true; -- rolled back: nothing was written
            WHEN SQLSTATE 'P0D02' THEN v_count := 0;   -- a node the plan refers to is not there: rolled back, nothing was written
        END;
        IF p_returns = 'STAMPS' THEN
            IF NOT v_stale AND v_result IS NOT NULL THEN
                RETURN NEXT v_result;
            END IF;
        ELSIF p_returns = 'EACH_STAMP' THEN
            IF NOT v_stale THEN
                RETURN QUERY SELECT unnest(v_each);
            END IF;
        ELSE
            RETURN NEXT v_count::text;
        END IF;
    END
    $fn$ LANGUAGE plpgsql;
    COMMENT ON TABLE ftranki_node IS 'drivine:7';
        END IF;
    END IF;
END
$ensure$

DO $ensure$
BEGIN
    IF obj_description(to_regclass('relatedrows_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
        PERFORM pg_advisory_xact_lock(hashtext('drivine:relatedrows'));
        -- Looked for again under the lock: another session may have made it while this one waited.
        IF obj_description(to_regclass('relatedrows_node'), 'pg_class') IS DISTINCT FROM 'drivine:7' THEN
            -- pgvector, for vector search, where the server has it and the user may make it: without it,
            -- everything but a vector search works.
            BEGIN
                CREATE EXTENSION IF NOT EXISTS vector;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            CREATE TABLE IF NOT EXISTS relatedrows_node (
        nid    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        labels jsonb NOT NULL,
        props  jsonb NOT NULL,
        stamp  varchar(33)
    );
    CREATE TABLE IF NOT EXISTS relatedrows_edge (
        eid   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        src   bigint NOT NULL REFERENCES relatedrows_node (nid) ON DELETE CASCADE,
        dst   bigint NOT NULL REFERENCES relatedrows_node (nid) ON DELETE CASCADE,
        type  varchar(128) NOT NULL,
        props jsonb NOT NULL DEFAULT '{}'
    );
    CREATE TABLE IF NOT EXISTS relatedrows_schema (
        kind        varchar(40) NOT NULL,
        label       varchar(400) NOT NULL,
        properties  varchar(2000) NOT NULL,
        name        varchar(400),
        object_name varchar(63),
        details     jsonb NOT NULL,
        PRIMARY KEY (kind, label, properties)
    );
    CREATE INDEX IF NOT EXISTS relatedrows_edge_src ON relatedrows_edge (src, type);
    CREATE INDEX IF NOT EXISTS relatedrows_edge_dst ON relatedrows_edge (dst, type);
    CREATE INDEX IF NOT EXISTS relatedrows_node_labels ON relatedrows_node USING GIN (labels jsonb_path_ops);
    CREATE OR REPLACE FUNCTION relatedrows_find(p_labels jsonb, p_key text, p_id text) RETURNS relatedrows_node AS $fn$
    DECLARE
        -- The lookup of a shape is prepared once a session and run by name after: written for the shape, it
        -- is planned for its label and property, and planned again each time it would cost a lookup several
        -- times over. The name is a hash of what the lookup is for, so it fits whatever the graph is called.
        v_name  text := 'drivine_find_' || md5('relatedrows' || ' ' || p_key || ' ' || p_labels::text);
        v_nid   bigint;
        v_row   relatedrows_node;
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_name) THEN
            -- Each label is a test of its own, as a statement writes it, so a partial index over one is used.
            EXECUTE format('PREPARE %I (text) AS SELECT min(n.nid) FROM relatedrows_node n WHERE (n.props ->> %L) = $1', v_name, p_key) ||
                COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(p_labels) l), '');
        END IF;
        LOOP
            EXECUTE format('EXECUTE %I(%L)', v_name, p_id) INTO v_nid;
            IF v_nid IS NULL THEN
                RETURN NULL;
            END IF;
            SELECT * INTO v_row FROM relatedrows_node n WHERE n.nid = v_nid FOR UPDATE;
            -- Locked: is it still the node that was looked for? Another writer may have changed it meanwhile.
            IF FOUND AND v_row.props ->> p_key = p_id AND v_row.labels @> p_labels THEN
                RETURN v_row;
            END IF;
        END LOOP;
    END
    $fn$ LANGUAGE plpgsql;
    CREATE OR REPLACE FUNCTION relatedrows_owns(p_bag jsonb, p_key text) RETURNS boolean AS $fn$
    DECLARE
        v_prefix   text := p_bag ->> 'prefix';
        v_reserved text;
    BEGIN
        -- A bag with a prefix owns the keys that begin with it; a flat bag, each key that is no one else's.
        IF NOT COALESCE((p_bag ->> 'flat')::boolean, false) THEN
            RETURN length(p_key) > COALESCE(length(v_prefix), 0) AND (v_prefix IS NULL OR left(p_key, length(v_prefix)) = v_prefix);
        END IF;
        IF COALESCE(p_bag -> 'reservedKeys', '[]'::jsonb) @> to_jsonb(p_key) THEN
            RETURN false;
        END IF;
        FOR v_reserved IN SELECT jsonb_array_elements_text(COALESCE(p_bag -> 'reservedPrefixes', '[]'::jsonb)) LOOP
            IF left(p_key, length(v_reserved)) = v_reserved THEN
                RETURN false;
            END IF;
        END LOOP;
        RETURN true;
    END
    $fn$ LANGUAGE plpgsql IMMUTABLE;
    CREATE OR REPLACE FUNCTION relatedrows_lowered(p_props jsonb, p_keys jsonb) RETURNS jsonb AS $fn$
    DECLARE
        v_props jsonb := p_props;
        v_key   text;
    BEGIN
        FOR v_key IN SELECT jsonb_array_elements_text(COALESCE(p_keys, '[]'::jsonb)) LOOP
            IF v_props ->> v_key IS NULL THEN
                v_props := v_props - ('__drivine.lower.' || v_key);
            ELSE
                v_props := v_props || jsonb_build_object('__drivine.lower.' || v_key, lower(v_props ->> v_key));
            END IF;
        END LOOP;
        RETURN v_props;
    END
    $fn$ LANGUAGE plpgsql STABLE;
    CREATE OR REPLACE FUNCTION relatedrows_write(p_plan jsonb, p_shapes jsonb, p_mark text, p_returns text, p_patched_if text) RETURNS SETOF text AS $fn$
    DECLARE
        v_op        jsonb;
        v_shape     jsonb;
        v_nodes     bigint[] := '{}';
        v_h_index   text[] := '{}';
        v_h_found   text[] := '{}';
        v_h_node    bigint[] := '{}';
        v_relinks   bigint[] := '{}';
        v_root      bigint;
        v_root_made boolean := false;
        v_was       text;
        v_carried   text;
        v_stamp     text;
        v_count     bigint := 0;
        v_result    text;
        v_each      text[] := '{}';
        v_stale     boolean := false;
        -- A node step's.
        v_row       relatedrows_node;
        v_nid       bigint;
        v_found     text;
        v_two       text;
        v_labels    jsonb;
        v_o         jsonb;
        v_expect    text;
        v_fresh     text;
        v_add       jsonb;
        v_drop      jsonb;
        v_made      boolean;
        v_tries     int;
        v_relabel   boolean;
        v_bag       jsonb;
        v_key       text;
        v_owned     jsonb;
        v_recorded  jsonb;
        v_now       jsonb;
        v_same      boolean;
        v_copied    jsonb;
        v_met       bigint;
        v_premade   jsonb := '{}';
        v_after     jsonb;
        v_pre       bigint;
        v_s         int;
        v_premade_as text;
        -- A relationship step's.
        v_from      bigint;
        v_to        bigint;
        v_type      text;
        v_dir       text;
        v_props     jsonb;
        v_clear     jsonb;
        v_e         record;
        v_x         jsonb;
        v_seen      int;
        v_unchanged int;
        v_ids       jsonb;
        v_held      jsonb;
        v_keep      boolean;
        v_delete    boolean;
        v_gone      bigint[];
        v_targets   bigint[];
        v_keys      text[];
        v_target    bigint;
        v_refs      bigint;
        v_removed   bigint;
    BEGIN
        BEGIN
            -- The nodes the plan makes, made together. A `node` step that does no more than write properties,
            -- with no stamp to check, no property bag to clear and no labels to own, makes its node by an
            -- insert alone when the node is not there; so for each shape the nodes of such steps that are not
            -- there are found by one lookup and inserted by one statement, the first step for each id only. A
            -- node a uniqueness constraint refuses, made by another writer at this moment, is not inserted
            -- here: its step finds it, or is refused, as it would be on its own. What each made gets is in
            -- `v_premade`, by shape and id, for its step to take below.
            -- Only where a shape has several such steps: for one node, the lookup and insert of its step are as cheap.
            FOR v_s IN
                SELECT (op ->> 's')::int FROM jsonb_array_elements(p_plan) op
                WHERE op ->> 'op' = 'node' AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                GROUP BY 1 HAVING count(*) > 1
            LOOP
                v_shape := p_shapes -> v_s;
                -- Prepared once a session for the shape, as a lookup is, and run by name after: planned afresh,
                -- it costs more than it saves a save of a few nodes. The name holds the store's version too, so
                -- a session that outlives an upgrade does not run what an earlier version prepared.
                v_premade_as := 'drivine_made_' || md5('drivine:7 relatedrows' || ' ' || (v_shape ->> 'key') || ' ' || (v_shape -> 'labels')::text);
                IF NOT EXISTS (SELECT 1 FROM pg_prepared_statements WHERE name = v_premade_as) THEN
                    EXECUTE format('PREPARE %I (jsonb, int) AS ', v_premade_as) || format($made$
                        WITH steps AS (
                            SELECT DISTINCT ON (op ->> 'k') ord, op FROM jsonb_array_elements($1) WITH ORDINALITY AS t (op, ord)
                            WHERE op ->> 'op' = 'node' AND (op ->> 's')::int = $2 AND op -> 'expect' IS NULL AND COALESCE((op ->> 'create')::boolean, true) AND op -> 'bags' IS NULL AND op -> 'owned' IS NULL AND op -> 'add' IS NULL AND op -> 'drop' IS NULL
                            ORDER BY op ->> 'k', ord),
                        absent AS (
                            SELECT s.ord, s.op FROM steps s
                            WHERE NOT EXISTS (SELECT 1 FROM relatedrows_node n WHERE (n.props ->> %L) = s.op ->> 'k'%s)),
                        made AS (
                            INSERT INTO relatedrows_node (labels, props, stamp)
                            SELECT op -> 'labels',
                                   relatedrows_lowered((jsonb_build_object(op ->> 'key', op -> 'id') || COALESCE(op -> 'set', '{}'::jsonb))
                                       - ARRAY(SELECT jsonb_array_elements_text(COALESCE(op -> 'unset', '[]'::jsonb))), op -> 'lower'),
                                   op ->> 'fresh'
                            FROM absent ORDER BY ord
                            ON CONFLICT DO NOTHING
                            RETURNING nid, props ->> %L AS k)
                        SELECT COALESCE(jsonb_object_agg(k, nid), '{}'::jsonb) FROM made
                    $made$, v_shape ->> 'key',
                        COALESCE((SELECT string_agg(format(' AND n.labels @> %L::jsonb', jsonb_build_array(l)), '') FROM jsonb_array_elements_text(v_shape -> 'labels') l), ''),
                        v_shape ->> 'key');
                END IF;
                EXECUTE format('EXECUTE %I(%L, %s)', v_premade_as, p_plan, v_s) INTO v_after;
                v_premade := v_premade || jsonb_build_object(v_s::text, v_after);
            END LOOP;

            FOR v_op IN SELECT value FROM jsonb_array_elements(p_plan) LOOP
                CASE v_op ->> 'op'
                WHEN 'node' THEN
                    -- Saves a node: found and locked, or made. What the step writes is worked out over the node as
                    -- it was found, and the node is written only where that differs from what it holds.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_expect := v_op ->> 'expect';
                    v_fresh := v_op ->> 'fresh';
                    v_tries := 0;
                    -- A node made with the others above is this step's, once: a later step for the same id finds it.
                    v_pre := (v_premade -> (v_op ->> 's') ->> (v_op ->> 'k'))::bigint;
                    IF v_pre IS NOT NULL THEN
                        v_premade := v_premade #- ARRAY[v_op ->> 's', v_op ->> 'k'];
                        v_nid := v_pre;
                        v_made := true;
                        v_found := NULL;
                    END IF;
                    WHILE v_pre IS NULL LOOP
                        v_row := relatedrows_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                        v_made := v_row.nid IS NULL;
                        IF v_made THEN
                            -- A checked save does not make the node again: it is gone, and the object is stale.
                            -- Nor does a step that makes no node.
                            IF v_expect IS NOT NULL OR NOT COALESCE((v_op ->> 'create')::boolean, true) THEN
                                RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                            END IF;
                            v_labels := v_op -> 'labels';
                            v_o := jsonb_build_object(v_op ->> 'key', v_op -> 'id');
                            v_stamp := NULL;
                        ELSIF COALESCE((v_op ->> 'absent')::boolean, false) THEN
                            -- A step that only makes the node writes nothing to one that is there.
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        ELSE
                            v_labels := v_row.labels;
                            v_o := v_row.props;
                            v_stamp := v_row.stamp;
                        END IF;
                        v_found := v_stamp;
                        IF v_expect IS NOT NULL AND (v_stamp IS NULL OR
                                CASE WHEN COALESCE((v_op ->> 'whole')::boolean, false) THEN v_stamp ELSE substr(v_stamp, 1, 16) END <> v_expect) THEN
                            RAISE EXCEPTION 'stale' USING ERRCODE = 'P0D01';
                        END IF;

                        -- The properties the step sets, and without those it unsets.
                        v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        -- The keys of each property bag the object no longer holds.
                        FOR v_bag IN SELECT value FROM jsonb_array_elements(COALESCE(v_op -> 'bags', '[]'::jsonb)) LOOP
                            FOR v_key IN SELECT jsonb_object_keys(v_o) LOOP
                                IF NOT COALESCE(v_bag -> 'keep', '[]'::jsonb) @> to_jsonb(v_key) AND relatedrows_owns(v_bag, v_key) THEN
                                    v_o := v_o - v_key;
                                END IF;
                            END LOOP;
                        END LOOP;

                        -- The labels an open label field holds are recorded on the node, so the node knows which are
                        -- its own. A step that clears replaces the record, and drops the labels recorded that the
                        -- field no longer holds, but for those of the class; one that does not adds to the record.
                        v_add := COALESCE(v_op -> 'add', '[]'::jsonb);
                        v_drop := COALESCE(v_op -> 'drop', '[]'::jsonb);
                        v_owned := v_op -> 'owned';
                        IF v_owned IS NOT NULL THEN
                            v_recorded := v_o -> (v_owned ->> 'prop');
                            IF v_recorded IS NULL OR jsonb_typeof(v_recorded) <> 'array' THEN
                                v_recorded := '[]'::jsonb;
                            END IF;
                            IF COALESCE((v_owned ->> 'clear')::boolean, false) THEN
                                v_drop := v_drop || COALESCE((
                                    SELECT jsonb_agg(l) FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l) AND NOT COALESCE(v_owned -> 'base', '[]'::jsonb) @> to_jsonb(l)), '[]'::jsonb);
                                IF jsonb_array_length(v_add) = 0 THEN
                                    v_o := v_o - (v_owned ->> 'prop');
                                ELSE
                                    v_o := v_o || jsonb_build_object(v_owned ->> 'prop', v_add);
                                END IF;
                            ELSIF jsonb_array_length(v_add) > 0 THEN
                                v_o := v_o || jsonb_build_object(v_owned ->> 'prop', COALESCE((
                                    SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM jsonb_array_elements_text(v_recorded) l
                                    WHERE NOT v_add @> to_jsonb(l)), '[]'::jsonb) || v_add);
                            END IF;
                        END IF;

                        -- The node's labels with those the step adds and without those it drops, in order; labels
                        -- that are as they were are not written again.
                        v_relabel := false;
                        IF jsonb_array_length(v_add) > 0 OR jsonb_array_length(v_drop) > 0 THEN
                            v_now := COALESCE((
                                SELECT jsonb_agg(l ORDER BY l COLLATE "C") FROM (
                                    SELECT jsonb_array_elements_text(v_labels) AS l UNION SELECT jsonb_array_elements_text(v_add)
                                ) a WHERE NOT v_drop @> to_jsonb(l)), '[]'::jsonb);
                            v_relabel := NOT (v_now @> v_labels AND v_labels @> v_now);
                            IF v_relabel OR v_made THEN
                                v_labels := v_now;
                            END IF;
                        END IF;

                        -- The copies are written from what the step leaves, and are no part of whether it changed the node.
                        v_copied := relatedrows_lowered(v_o, v_op -> 'lower');
                        IF v_made THEN
                            -- A node that is made is written once, whole, with a stamp of its own. A uniqueness
                            -- constraint may refuse it: once, it may be that another writer made the node at this
                            -- moment, and the node is looked for again. Found again or not, the constraint is on
                            -- something other than this node's key, and refuses this save.
                            v_stamp := v_fresh;
                            INSERT INTO relatedrows_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp) ON CONFLICT DO NOTHING RETURNING nid INTO v_nid;
                            IF v_nid IS NOT NULL THEN
                                EXIT;
                            END IF;
                            v_tries := v_tries + 1;
                            IF v_tries > 1 THEN
                                INSERT INTO relatedrows_node (labels, props, stamp) VALUES (v_labels, v_copied, v_stamp);
                            END IF;
                        ELSE
                            v_nid := v_row.nid;
                            v_same := v_o = v_row.props;
                            -- A new first token only if the step changes the node, or the node has no stamp of two tokens yet.
                            v_two := CASE WHEN length(v_stamp) = 33 AND substr(v_stamp, 17, 1) = ':' THEN v_stamp END;
                            IF v_two IS NULL OR NOT v_same OR v_relabel THEN
                                v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                                IF v_relabel THEN
                                    UPDATE relatedrows_node SET labels = v_labels WHERE nid = v_nid;
                                END IF;
                                IF v_copied <> v_row.props THEN
                                    UPDATE relatedrows_node SET props = v_copied, stamp = v_stamp WHERE nid = v_nid;
                                ELSE
                                    UPDATE relatedrows_node SET stamp = v_stamp WHERE nid = v_nid;
                                END IF;
                            ELSIF v_copied <> v_row.props THEN
                                -- Only a copy was out of step with its property: the node keeps its stamp.
                                UPDATE relatedrows_node SET props = v_copied WHERE nid = v_nid;
                            END IF;
                            EXIT;
                        END IF;
                    END LOOP;

                    v_nodes[(v_op ->> 'r')::int + 1] := v_nid;
                    IF v_op ->> 'i' IS NOT NULL THEN
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        -- Nothing for a node the step made, and a mark for one that was there without a stamp.
                        v_h_found := array_append(v_h_found, CASE WHEN v_made THEN NULL ELSE COALESCE(v_found, '-') END);
                        v_h_node := array_append(v_h_node, v_nid);
                    END IF;
                    IF COALESCE((v_op ->> 'root')::boolean, false) THEN
                        v_root := v_nid;
                        v_root_made := v_made;
                        v_was := v_found;
                        v_carried := v_op ->> 'carried';
                    END IF;

                WHEN 'ref' THEN
                    -- Finds a node that must be there, and locks it.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_row := relatedrows_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NULL THEN
                        RAISE EXCEPTION 'absent' USING ERRCODE = 'P0D02';
                    END IF;
                    v_nodes[(v_op ->> 'r')::int + 1] := v_row.nid;

                WHEN 'link' THEN
                    -- Joins two nodes. The relationship is as the step says only if every one of its type between them is.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := v_nodes[(v_op ->> 'to')::int + 1];
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_props := COALESCE(v_op -> 'props', '{}'::jsonb);
                    v_clear := COALESCE(v_op -> 'clear', '[]'::jsonb);
                    v_seen := 0;
                    v_unchanged := 0;
                    IF NOT COALESCE((v_op ->> 'always')::boolean, false) THEN
                        -- A node's relationship to itself is one relationship, whichever way it is read.
                        FOR v_e IN
                            SELECT eid, props FROM relatedrows_edge
                            WHERE type = v_type AND (
                                (v_dir IN ('OUT', 'BOTH') AND src = v_from AND dst = v_to)
                                OR ((v_dir = 'IN' OR (v_dir = 'BOTH' AND v_from <> v_to)) AND src = v_to AND dst = v_from))
                            ORDER BY eid
                        LOOP
                            v_seen := v_seen + 1;
                            v_x := (v_e.props || v_props) - ARRAY(SELECT jsonb_array_elements_text(v_clear));
                            IF v_x = v_e.props THEN
                                v_unchanged := v_unchanged + 1;
                            ELSE
                                UPDATE relatedrows_edge SET props = v_x WHERE eid = v_e.eid;
                            END IF;
                        END LOOP;
                    END IF;
                    IF v_seen = 0 THEN
                        -- An undirected field is satisfied by a relationship either way, and makes one from the first node.
                        INSERT INTO relatedrows_edge (src, dst, type, props)
                        VALUES (CASE WHEN v_dir = 'IN' THEN v_to ELSE v_from END, CASE WHEN v_dir = 'IN' THEN v_from ELSE v_to END, v_type, v_props);
                    END IF;
                    IF v_seen = 0 OR v_unchanged < v_seen THEN
                        v_relinks := v_relinks || v_from || v_to;
                    END IF;
                    v_count := v_count + GREATEST(v_seen, 1);

                WHEN 'unlink' THEN
                    -- Removes a field's relationships to the targets whose ids the step names, or to every target but those.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    v_ids := COALESCE(v_op -> 'ids', '[]'::jsonb);
                    v_held := COALESCE(v_op -> 'held', '[]'::jsonb);
                    v_keep := COALESCE((v_op ->> 'keep')::boolean, false);
                    v_delete := COALESCE((v_op ->> 'delete')::boolean, false);
                    v_gone := '{}';
                    v_targets := '{}';
                    v_keys := '{}';
                    -- A relationship from the node to itself is read as leaving it, and so once when both directions are read.
                    FOR v_e IN
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key') AS key
                        FROM relatedrows_edge e JOIN relatedrows_node t ON t.nid = e.dst
                        WHERE v_dir IN ('OUT', 'BOTH') AND e.src = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                        UNION ALL
                        SELECT e.eid, t.nid, t.props ->> (v_shape ->> 'key')
                        FROM relatedrows_edge e JOIN relatedrows_node t ON t.nid = e.src
                        WHERE v_dir IN ('IN', 'BOTH') AND e.dst = v_from AND e.type = v_type AND t.labels @> (v_shape -> 'labels')
                          AND (v_dir = 'IN' OR e.src <> v_from)
                    LOOP
                        IF v_e.key IS NOT NULL AND (v_ids @> to_jsonb(v_e.key)) <> v_keep THEN
                            v_gone := array_append(v_gone, v_e.eid);
                            v_targets := array_append(v_targets, v_e.nid);
                            v_keys := array_append(v_keys, v_e.key);
                        END IF;
                    END LOOP;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- A target gone since the relationships were read has nothing left to remove or count.
                            PERFORM 1 FROM relatedrows_node WHERE nid = v_target FOR UPDATE;
                            IF NOT FOUND THEN
                                CONTINUE;
                            END IF;
                            -- What refers to a target is a relationship on the side this field reaches it from: counted before any is removed.
                            v_refs := 0;
                            IF v_delete THEN
                                IF v_dir IN ('OUT', 'BOTH') THEN
                                    SELECT count(*) INTO v_refs FROM relatedrows_edge WHERE dst = v_target;
                                END IF;
                                IF v_dir IN ('IN', 'BOTH') THEN
                                    -- A relationship from the node to itself is counted once.
                                    SELECT v_refs + count(*) INTO v_refs FROM relatedrows_edge WHERE src = v_target AND (v_dir = 'IN' OR dst <> v_target);
                                END IF;
                            END IF;
                            SELECT count(*) INTO v_removed FROM unnest(v_targets) t WHERE t = v_target;
                            SELECT k INTO v_key FROM unnest(v_targets, v_keys) AS u (t, k) WHERE t = v_target LIMIT 1;
                            -- The root is never deleted, and nor is a node the object still holds in another field.
                            IF v_delete AND v_target <> v_from AND v_refs = v_removed AND NOT v_held @> to_jsonb(v_key) THEN
                                v_relinks := array_remove(v_relinks, v_target);
                                DELETE FROM relatedrows_node WHERE nid = v_target;
                            ELSE
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM relatedrows_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'cut' THEN
                    -- Removes the relationships of a type from one node to another, or with no other node named to any in a direction.
                    v_from := v_nodes[(v_op ->> 'from')::int + 1];
                    v_to := CASE WHEN v_op ->> 'to' IS NOT NULL THEN v_nodes[(v_op ->> 'to')::int + 1] END;
                    v_type := v_op ->> 'type';
                    v_dir := v_op ->> 'dir';
                    SELECT COALESCE(array_agg(c.eid), '{}'), COALESCE(array_agg(c.far), '{}') INTO v_gone, v_targets FROM (
                        SELECT eid, dst AS far FROM relatedrows_edge
                        WHERE v_dir IN ('OUT', 'BOTH') AND src = v_from AND type = v_type AND (v_to IS NULL OR dst = v_to)
                        UNION ALL
                        SELECT eid, src FROM relatedrows_edge
                        WHERE v_dir IN ('IN', 'BOTH') AND dst = v_from AND type = v_type AND (v_to IS NULL OR src = v_to) AND (v_dir = 'IN' OR src <> v_from)
                    ) c;
                    IF cardinality(v_gone) > 0 THEN
                        FOR v_target IN SELECT DISTINCT t FROM unnest(v_targets) t ORDER BY t LOOP
                            -- An end gone since the relationships were read took them with it, and has no token to change.
                            PERFORM 1 FROM relatedrows_node WHERE nid = v_target FOR UPDATE;
                            IF FOUND THEN
                                v_relinks := array_append(v_relinks, v_target);
                            END IF;
                        END LOOP;
                        DELETE FROM relatedrows_edge WHERE eid = ANY (v_gone);
                        v_relinks := array_append(v_relinks, v_from);
                        v_count := v_count + cardinality(v_gone);
                    END IF;

                WHEN 'patch' THEN
                    -- Writes properties to a node that is there, and makes none. One that is not there is left out of
                    -- what the call hands back; one that does not meet the predicate is left as it is, and said to.
                    v_shape := p_shapes -> ((v_op ->> 's')::int);
                    v_fresh := v_op ->> 'fresh';
                    v_row := relatedrows_find(v_shape -> 'labels', v_shape ->> 'key', v_op ->> 'k');
                    IF v_row.nid IS NOT NULL THEN
                        v_met := 1;
                        IF p_patched_if IS NOT NULL THEN
                            -- The node is locked: what the predicate reads of it is what the last writer committed.
                            EXECUTE p_patched_if INTO v_met USING v_row.nid;
                        END IF;
                        v_o := v_row.props;
                        IF v_met > 0 THEN
                            v_o := (v_o || COALESCE(v_op -> 'set', '{}'::jsonb)) - ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_op -> 'unset', '[]'::jsonb)));
                        END IF;
                        v_same := v_o = v_row.props;
                        -- A node the step changes has its copies written from what it now holds.
                        IF NOT v_same THEN
                            v_o := relatedrows_lowered(v_o, v_op -> 'lower');
                        END IF;
                        v_two := CASE WHEN length(v_row.stamp) = 33 AND substr(v_row.stamp, 17, 1) = ':' THEN v_row.stamp END;
                        IF v_two IS NULL OR NOT v_same THEN
                            v_stamp := substr(v_fresh, 1, 16) || COALESCE(substr(v_two, 17), substr(v_fresh, 17));
                            IF NOT v_same THEN
                                UPDATE relatedrows_node SET props = v_o, stamp = v_stamp WHERE nid = v_row.nid;
                            ELSE
                                UPDATE relatedrows_node SET stamp = v_stamp WHERE nid = v_row.nid;
                            END IF;
                        END IF;
                        v_h_index := array_append(v_h_index, v_op ->> 'i');
                        v_h_found := array_append(v_h_found, CASE WHEN v_met = 0 THEN '-' WHEN NOT v_same THEN '1' ELSE '0' END);
                        v_h_node := array_append(v_h_node, v_row.nid);
                    END IF;
                END CASE;
            END LOOP;

            -- Each node whose relationships changed gets a new second token, once. Every one of them is locked
            -- already, found and locked by its step or made by it, so one statement writes them all and waits
            -- for no lock. A stamp that is not two tokens, which no save leaves, is replaced whole.
            IF cardinality(v_relinks) > 0 THEN
                UPDATE relatedrows_node SET stamp = COALESCE(substr(CASE WHEN length(stamp) = 33 AND substr(stamp, 17, 1) = ':' THEN stamp END, 1, 17), substr(p_mark, 1, 17)) || substr(p_mark, 18)
                WHERE nid = ANY (v_relinks);
            END IF;

            IF p_returns = 'STAMPS' THEN
                -- The root's stamp, keeping the object's own token wherever the node had another when the save
                -- began, then `index/found=stamp` for each node whose stamp is handed back.
                SELECT stamp INTO v_stamp FROM relatedrows_node WHERE nid = v_root;
                IF v_carried IS NULL THEN
                    -- An object that carried no stamp is handed the whole stamp only of a node its save made.
                    IF NOT v_root_made THEN
                        v_stamp := substr(v_stamp, 1, 17);
                    END IF;
                ELSIF v_was = v_carried THEN
                    NULL; -- found exactly as loaded: the node's stamp is handed back whole
                ELSE
                    v_stamp := CASE WHEN substr(v_was, 1, 16) = substr(v_carried, 1, 16) THEN substr(v_stamp, 1, 16) ELSE substr(v_carried, 1, 16) END || ':' ||
                        CASE WHEN NULLIF(substr(v_was, 18), '') = NULLIF(substr(v_carried, 18), '') OR (v_root_made AND NULLIF(substr(v_carried, 18), '') IS NULL)
                             THEN substr(v_stamp, 18) ELSE substr(v_carried, 18) END;
                END IF;
                -- Every handed-back stamp is read by one query, in the order the steps came.
                SELECT v_stamp || COALESCE(string_agg(',' || h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, ''), '' ORDER BY h.ord), '')
                INTO v_result
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN relatedrows_node n ON n.nid = h.nid;
            ELSIF p_returns = 'EACH_STAMP' THEN
                SELECT COALESCE(array_agg(h.i || '/' || COALESCE(h.found, '') || '=' || COALESCE(n.stamp, '') ORDER BY h.ord), '{}')
                INTO v_each
                FROM unnest(v_h_node, v_h_index, v_h_found) WITH ORDINALITY AS h (nid, i, found, ord) LEFT JOIN relatedrows_node n ON n.nid = h.nid;
            END IF;
        EXCEPTION
            WHEN SQLSTATE 'P0D01' THEN v_stale := true; -- rolled back: nothing was written
            WHEN SQLSTATE 'P0D02' THEN v_count := 0;   -- a node the plan refers to is not there: rolled back, nothing was written
        END;
        IF p_returns = 'STAMPS' THEN
            IF NOT v_stale AND v_result IS NOT NULL THEN
                RETURN NEXT v_result;
            END IF;
        ELSIF p_returns = 'EACH_STAMP' THEN
            IF NOT v_stale THEN
                RETURN QUERY SELECT unnest(v_each);
            END IF;
        ELSE
            RETURN NEXT v_count::text;
        END IF;
    END
    $fn$ LANGUAGE plpgsql;
    COMMENT ON TABLE relatedrows_node IS 'drivine:7';
        END IF;
    END IF;
END
$ensure$

